window.HOP_BROWSE_ROWS = [{"id": "986b773cd94a", "instructor": "Marcelo Garcia", "instructional": "Butterfly by Marcelo Garcia", "volume": "Butterfly by Marcelo Garcia - S01E01 - Volume 1.mp4", "chapter_title": "BUTTERFLY SWEEP PROCESS", "chapter_start": 1055.0, "named_move": "Butterfly sweep", "ruleset": "no-gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "top", "end_position": "half-guard", "technique_steps": "1. Butterfly guard, bottom: close the distance with a strong posture, elbows closed but able to maneuver, and attack so the opponent has to defend.\n2. Take a good underhook: send the hand deeper, higher and farther, and keep the elbow up rather than clamping it down.\n3. Push his elbow in and concentrate on keeping that arm in; do not push the elbow back and do not pull it in.\n4. Once the underhook is clamped and the elbow is in, go immediately with the sweep; do not hold that position.\n5. Close the distance with the hook, bringing the butt as close as possible to the heels.\n6. Scoop and pull his weight off the ground, then guide that weight so his back goes to the floor, not onto you.\n7. Lift as high as needed while turning halfway so your shoulder and side go to the floor, not a flat back.\n8. Keep the lifting knee pointed up and out, never in, until he falls, so the knee does not buckle and collapse the sweep.\n9. Post the other knee close, down, and closed to help get him off the ground, then lift that hook as well.\n10. Come up and hold the top position, even if the landing is half guard.", "main_ideas": "Attack so he has to defend; a deep no-gi underhook with the elbow up only works if you push his elbow in and go immediately. Scoop him off the ground and turn onto your shoulder so his back hits the mat, not you. Keep the lifting knee pointed out until he falls, and hold top even if you land in half guard.", "source_time_ranges": ["1036.24-1603.98"]}, {"id": "c6293d8aa15a", "instructor": "Marcelo Garcia", "instructional": "Butterfly by Marcelo Garcia", "volume": "Butterfly by Marcelo Garcia - S01E01 - Volume 1.mp4", "chapter_title": "SHOOT & RESHOOT", "chapter_start": 1627.0, "named_move": "Butterfly sweep", "ruleset": "no-gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "top", "end_position": "mount*", "technique_steps": "1. Butterfly guard, bottom: close the distance and commit to the sweep.\n2. When the opponent sinks his weight back so you are not close enough to finish, stay in the middle instead of falling back or backing away to reset.\n3. Scoop forward from there and get under again without going back to sit up.\n4. Compress the same sweep and reshoot immediately so he does not have time to stop you twice.", "main_ideas": "Do not back away when he sinks his weight and shuts the first sweep. Reshoot from the middle on a quicker beat so he has to stop you twice.", "source_time_ranges": ["1637.22-1869.25"]}, {"id": "f901a42e5d5f", "instructor": "Marcelo Garcia", "instructional": "Butterfly by Marcelo Garcia", "volume": "Butterfly by Marcelo Garcia - S01E01 - Volume 1.mp4", "chapter_title": "FAR SIDE SWEEP TO COUNTER UNDERHOOK PASS", "chapter_start": 1897.0, "named_move": "Butterfly sweep*", "ruleset": "no-gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "top", "end_position": "mount*", "technique_steps": "1. Butterfly guard, bottom: close the distance and engage with the butterfly sweep setup.\n2. When the opponent is stronger, changes your angle, and drives you the opposite way, go to the mat first, accelerating his dump so you arrive ahead of his move.\n3. As you drop, before he closes into you, frame with the free arm; one arm may already be stuck.\n4. As soon as you have space, repummel and suck the stuck hand out.\n5. Get both hands in front of him and sit up; even without a full sit-up, pummel the underhook and work your way up.\n6. Use your hook to push him off you so you can dig under again.\n7. Get under, secure the underhook, and control him.\n8. Rebuild the same butterfly sweep toward the opposite side: push his elbow in and pick him out of the ground.\n9. As soon as you sit up or get up on your knee, keep moving forward, close the distance, and complete the opposite-side sweep.", "main_ideas": "When he dumps you the other way, get to the mat first, frame, and rebuild the same sweep to the opposite side. Reconnect immediately; waiting lets him pin or pass the other underhook.", "source_time_ranges": ["1908.40-2242.40"]}, {"id": "8beb21c9e170", "instructor": "Marcelo Garcia", "instructional": "Butterfly by Marcelo Garcia", "volume": "Butterfly by Marcelo Garcia - S01E01 - Volume 1.mp4", "chapter_title": "2-ON-1 SWEEP", "chapter_start": 2248.0, "named_move": "2-on-1 sweep*", "ruleset": "no-gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "top", "end_position": "mount*", "technique_steps": "1. Butterfly guard, bottom: close the distance, looking for hand control, elbow control, an underhook, or a double underhook.\n2. When the opponent has one knee up, take a two-on-one on the opposite arm (right arm if the left knee is up), controlling the elbow and the wrist. The wrist can come from grabbing the top or grabbing the body.\n3. Connect the two-on-one only long enough to scoop forward and get the butt close to the heels.\n4. Lift with the (inside) hook while maintaining the two-on-one on the arm.\n5. Walk the feet in to stay close as the opponent is thrown, so he cannot use the momentum to recover to his knees.\n6. Get the feet on the ground and come up on top, taking the underhook if available.", "main_ideas": "When one knee is up, take the two-on-one on the opposite arm and only help him fall; do not hold the grip. Follow faster than you throw him so you finish on top. If the other knee is up, look for single-leg X, an ankle pick, or a single leg instead.", "source_time_ranges": ["2242.40-2565.04"]}, {"id": "08824c5c6d1b", "instructor": "Marcelo Garcia", "instructional": "Butterfly by Marcelo Garcia", "volume": "Butterfly by Marcelo Garcia - S01E01 - Volume 1.mp4", "chapter_title": "KICK SPIN BACKTAKE", "chapter_start": 2580.0, "named_move": "Kick spin backtake*", "ruleset": "no-gi", "move_type": "back-take", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "top", "end_position": "back-control", "technique_steps": "1. Butterfly guard, bottom: close the distance. His knee is down. Get a two-on-one and hold it solid.\n2. When the two-on-one is strong, pick him up as high as you can instead of sweeping, so you have room to circle him.\n3. Use the two-on-one to rotate him and the hook to lift him high, and make him turn.\n4. Halfway, take one hook out so he falls inside your hooks; as he turns, the remaining butterfly hook becomes a back hook.\n5. Scoop and keep him up, bring him high, and push the controlled arm away.\n6. At the same time, one hand goes over the shoulder and the other hand keeps this out. Put the other hook if you can.\n7. Establish his back and start looking to get a choke.", "main_ideas": "When the knee is down, pick him high off a solid two-on-one and dump him into the remaining hook as it becomes a back hook. Throw first; the back lets you score and finish.", "source_time_ranges": ["2596.78-2825.60"]}, {"id": "31c198c67e93", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E01 - Leg Locks - Enter the System.mp4", "chapter_title": "Immovable Elbow", "chapter_start": 2005.0, "named_move": "Immovable Elbow", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom*", "start_position": "closed-guard*", "end_occupancy": "neutral*", "end_position": "standing*", "technique_steps": "1. From bottom, secure a two-on-one grip on the opponent's wrist or elbow. 2. Bring elbows to your hips and shoulders forward so the grip is anchored by elbow-to-hip structure rather than hand strength. 3. As the opponent pulls back, move with the resistance, stepping the feet one at a time rather than pushing both into the mat. 4. Continue walking along the mat until the opponent is tripped down to the floor.", "main_ideas": "Anchor grips at the elbow-to-hip. Move with resistance, never against it. Flow grip to grip.", "source_time_ranges": []}, {"id": "5ad789432fc8", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E01 - Leg Locks - Enter the System.mp4", "chapter_title": "2 on 1 Leg", "chapter_start": 3143.0, "named_move": "Two-on-one leg grip into ashigarami", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "neutral", "end_position": "ashigarami*", "technique_steps": "1. Opponent, facing you on two knees or standing, posts a leg to the outside of your feet.\n2. Snatch the posted leg with one hand below the knee and one hand above the knee, wrist-deep at calf and thigh.\n3. Place your knee directly behind the opponent's knee, fitting the top of your knee into the pocket behind his.\n4. Use your feet to pull your body in, driving your knee back toward your chest to draw the opponent's body to you.\n5. Keep the hands in place only to stop the leg from stepping off your knee.\n6. Bring the feet up and fit the ashigarami in place.", "main_ideas": "Snatch the posted leg with a two-on-one grip. Put your knee behind his knee. Drive your knee to your chest to bring him in.", "source_time_ranges": []}, {"id": "a266753b390f", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E01 - Leg Locks - Enter the System.mp4", "chapter_title": "shin To Shin", "chapter_start": 3409.0, "named_move": "Shin-to-shin inside position recovery (two-on-one post and wide-leg pommel)", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "neutral*", "start_position": "shin-to-shin", "end_occupancy": "neutral*", "end_position": "shin-to-shin*", "technique_steps": "1. Start in shin-to-shin with the opponent's foot on the inside. 2. Take a two-on-one grip and post on the training partner's knee to stop the knee drive. 3. Take your leg out wide, keeping elbows close to your hip to block. 4. Pommel your foot in from the wide angle. 5. Go around the corner and lock up wrist-deep, palm down, on the partner's leg. 6. Place your knee in the partner's hip and extend to regain inside position, back into the ashigarami game.", "main_ideas": "Stop the knee drive first. Take your leg out wide before you pommel in. Go wrist-deep and palm-down to lock up the inside position.", "source_time_ranges": []}, {"id": "6900d672b9d5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E01 - Leg Locks - Enter the System.mp4", "chapter_title": "Standing Opponent", "chapter_start": 3651.0, "named_move": "Shin-on-shin standing grip control (hook and snake calf grip)", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "shin-to-shin", "end_occupancy": "bottom", "end_position": "shin-to-shin", "technique_steps": "1. Sit on the butt facing the standing opponent in shin-to-shin with his leg in front of you. 2. Hook your shoelaces inside his ankle and actively retract the toes toward your knee. 3. Scoot the body forward and go wrist-deep, palm down, snaking the hand around his calf. 4. Bring elbow and knee close together so foot and hand grips cover each other's weakness. 5. If he steps back, pull your left hand to your right to bring his other foot to your hand; if he puts hands on the mat, post on his upper body and move into ashigarami.", "main_ideas": "Hook the ankle with active toes. Snake the calf deep and tie elbow to knee. Control the second leg by bringing it to your hand.", "source_time_ranges": []}, {"id": "eebd49fcf9fb", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E01 - Leg Locks - Enter the System.mp4", "chapter_title": "scoop gripping", "chapter_start": 3933.0, "named_move": "Scoop grip from bottom after catching a posted leg", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "half-guard", "end_occupancy": "bottom", "end_position": "leg-drag-position*", "technique_steps": "1. Start on two knees in the upper-body grip game with the opponent in front of you.\n2. Watch for the opponent to post a leg.\n3. Go through and catch the posted leg to hold it in place.\n4. Off the catch, go through and take the scoop grip: one hand at the upper leg, elbow at the lower leg.\n5. Use the scoop to pull the opponent's center of gravity under yours as he tries to walk away, entering the leg game.", "main_ideas": "Catch the posted leg before it leaves.\nTake the scoop grip, one hand upper leg, elbow lower leg.\nPull the opponent's weight onto your legs with the scoop.", "source_time_ranges": []}, {"id": "d43202bad546", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E01 - Leg Locks - Enter the System.mp4", "chapter_title": "Ankle Gripping", "chapter_start": 4276.0, "named_move": "Supine Ankle Grip into Ashigarami Entry", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "back-control", "end_occupancy": "neutral", "end_position": "ashigarami*", "technique_steps": "1. Lying supine, establish inside foot position on the opponent's back leg, hooking in before the opponent can pass or throw your legs.\n2. Shoot the hand down and catch the opponent's ankle, forearm over the shoelaces, pinky knuckle close to the mat, gripping the end of the lever.\n3. Hug the grabbed foot into your hip or buttocks so the opponent cannot kick it out.\n4. Take the leg around the corner and place the knee behind the opponent's knee, drawing him forward with the knee-to-chest and the opposite knee pushing out.\n5. Fire the legs up into the Ashigarami position, ending in the leg-game attacking setup.", "main_ideas": "Grip the ankle precisely at the shoelaces with the pinky knuckle low.\nHug the foot into your hip so it cannot be kicked out.\nPull with your legs, not your hands, and finish into Ashigarami.", "source_time_ranges": []}, {"id": "f342863def4a", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Attaining Inside", "chapter_start": 0, "named_move": "Closed guard to butterfly guard via pummel and forward shift", "ruleset": "both*", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "neutral", "end_position": "butterfly-guard", "technique_steps": "1. From closed guard with upper-body pushing grips on the opponent's biceps, flatten the legs and turn across the training partner to gain angle.\n2. Pummel one foot to an inside position on the opponent's legs.\n3. Plant the second foot and pummel it out in the other direction so both feet are inside.\n4. Execute a forward shift: bring knees to chest to get under center of gravity and lift the opponent off the mat along the floor line, moving from supine to seated.\n5. Finish seated in butterfly guard with inside foot control and upper-body grips.", "main_ideas": "Gain angle before anything else. Pummel one leg at a time. Shift forward along the floor to sit up.", "source_time_ranges": []}, {"id": "701007fe990f", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Standing Opponent", "chapter_start": 300.0, "named_move": "Closed guard stand-up pommel to X-guard", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "x-guard", "technique_steps": "1. From closed guard with the opponent standing, hold an outside grip on one side and an inside grip on the other.\n2. Pivot off the opponent's hips and open the guard, dropping the right knee to the inside position.\n3. Pommel the foot to inside position to off-balance the opponent.\n4. Release and move the leg that creates sufficient angle.\n5. Pommel into X-guard.\n6. Get the opponent's hands down to the mat and enter the Kazushi game.", "main_ideas": "Grip outside and inside on opposite sides. Drop the knee inside as you open the guard. Pommel the leg to inside position and build angle before entering X-guard.", "source_time_ranges": []}, {"id": "b6ddbd249e8d", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "De La Riva", "chapter_start": 469.0, "named_move": "De La Riva to X-Guard via shin grip and off-balance", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "de-la-riva", "end_occupancy": "bottom", "end_position": "x-guard", "technique_steps": "1. From De La Riva, punch the hand through elbow-deep and release the shoelace control of the hamstring. 2. Grab your own shin with that hand. 3. Off-balance the opponent over your right shoulder using your right foot and leg lift to get their hands down to the mat. 4. Pummel the free foot through and around, switching to a scoop grip. 5. Convert into X-Guard.", "main_ideas": "Punch through and grab your own shin. Off-balance the opponent so their hands go to the mat. Pummel through and scoop into X-Guard.", "source_time_ranges": ["0.00-0.00"]}, {"id": "5c374b2a3831", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "De La Riva", "chapter_start": 469.0, "named_move": "X-Guard to reverse X-Guard with hands down", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "x-guard", "end_occupancy": "bottom", "end_position": "reverse-x-guard*", "technique_steps": "1. Maintain X-Guard while keeping the opponent's hands down on the mat. 2. Make the switch to reverse X-Guard by kicking around the corner. 3. Control the training partner into a winning position from reverse X.", "main_ideas": "Keep their hands down. Switch to reverse X by kicking around the corner. Punch through into an attacking position.", "source_time_ranges": ["0.00-0.00"]}, {"id": "8e281bc539b7", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Pummelling Legs Top Position", "chapter_start": 737.0, "named_move": "Pummel to inside position from seated opponent (toe line approach)", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "half-guard*", "end_occupancy": "top", "end_position": "inside-ashi*", "technique_steps": "1. From a staggered stance, step up to the opponent's toe line, not past it.\n2. Post the rear hand on the opponent as resistance; keep the lead hand as a down-block.\n3. Cross-grip the opponent's wrist to deny the outside hand; if he pulls away, take the other hand.\n4. Step the inside leg over his ankles into the inside space.\n5. Drive forward and push his shoulders behind his hips to break his stance.\n6. As he recovers, you hold inside position with at least one foot and move to a passing or leg game.", "main_ideas": "Step only to the toe line. Post and block so he cannot double-grip. Cross-grip the wrist, step over the ankles, and break his posture.", "source_time_ranges": []}, {"id": "534ddcbb4387", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Movement Inside", "chapter_start": 1120.0, "named_move": "Crescent step fake pass to inside position", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "standing", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. Stand staggered and slightly upright in front of the seated opponent, posting on him. 2. Cross step while posting on him and side step out beyond the line of his knee. 3. Take a wide crescent step around his leg, pointing your foot inward. 4. The opponent must react and push, post, and scoot, separating his feet. 5. Step your foot inside to take inside position.", "main_ideas": "Use the crescent step to force movement.\nIf he does not move, he gives you the back.\nTake the inside when his feet open.", "source_time_ranges": []}, {"id": "1a8d0084a4b5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Movement Inside", "chapter_start": 1120.0, "named_move": "Fake crescent step and re-entry", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "standing", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. Side step and put your leg around the corner as a fake crescent step. 2. Watch for the opponent to follow with his right leg. 3. Enter with your right foot into the space created. 4. Follow with the other foot to hold inside position.", "main_ideas": "Fake the crescent to draw his movement.\nEnter when his foot follows.", "source_time_ranges": []}, {"id": "d52b62dfab98", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Movement Inside", "chapter_start": 1120.0, "named_move": "Fake switch back in", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "standing", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. Side step off the initial fake. 2. Fake a switch. 3. Go back in and take the foot inside as he reacts.", "main_ideas": "Side step, fake the switch, then go back in.", "source_time_ranges": []}, {"id": "899ee97af663", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Movement Inside", "chapter_start": 1120.0, "named_move": "Catch and drop to inside position", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "standing", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. Post on the opponent and go in with the hands. 2. Bring both hands down to catch his legs. 3. Drop and let your feet take the inside as he recovers his position.", "main_ideas": "Catch the legs, then drop.\nYour feet take inside as he recovers.", "source_time_ranges": []}, {"id": "13dc3590eb7d", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Movement Inside", "chapter_start": 1120.0, "named_move": "Push-pull rise to separate knees", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "knee-on-belly*", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. From knees, play the push-pull dynamic. 2. Rise up onto your heels. 3. Place one hand on the collar and one on the knee to separate the legs. 4. Put your foot up on the inside as he recovers.", "main_ideas": "Rise onto your heels to move.\nUse collar and knee to separate.", "source_time_ranges": []}, {"id": "08d1e6f5754e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Supine Opponent", "chapter_start": 1507.0, "named_move": "Pommel to inside position against supine sticky hook", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "Supine opponent with two sticky hooks, owning inside position", "end_occupancy": "top", "end_position": "Both legs inside opponent's legs", "technique_steps": "1. Start with opponent in supine guard with both feet hooked sticky behind your knees, owning inside position. 2. Post both hands on opponent's knees. 3. Turn one knee inward to negate that hook, putting both hands on the knee. 4. Put all weight over the other leg. 5. Lift the freed foot toward your buttocks. 6. Pommel that leg through to the inside position. 7. Turn the second knee inward, put weight on the opposite leg, lift that foot to your buttocks, and pommel it inside. 8. Finish with both legs inside the opponent's legs, ready to enter leg locks.", "main_ideas": "Turn one knee at a time, never both. Put weight on the opposite leg before pommeling. Finish with both legs inside.", "source_time_ranges": []}, {"id": "a7bd8ded7648", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Supine Opponent", "chapter_start": 1507.0, "named_move": "Back step entry to cross ashi-garami from one leg inside", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "One leg inside opponent's legs, opponent owning the other side", "end_occupancy": "top", "end_position": "cross ashi-garami", "technique_steps": "1. Start with one leg already inside opponent's legs. 2. Pull the second leg out. 3. Post on the mat. 4. Back step that leg over the opponent's legs to reach the cross ashi-garami position.", "main_ideas": "Pull the second leg out and post. Back step over the legs once one leg is inside.", "source_time_ranges": []}, {"id": "6fef38a6bc15", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Supine Opponent", "chapter_start": 1507.0, "named_move": "Turn, pommel one leg in, free leg, back step to cross ashi-garami", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "No legs inside opponent's legs", "end_occupancy": "top", "end_position": "cross ashi-garami", "technique_steps": "1. Start with no legs inside opponent's legs. 2. Turn one knee inward. 3. Pommel one leg inside. 4. Free the other leg. 5. Back step over the opponent's legs to reach cross ashi-garami.", "main_ideas": "Turn, pommel in, free the leg, then back step.", "source_time_ranges": []}, {"id": "4d2bf7c901a3", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Hand Post - Leg Pummeling", "chapter_start": 1929.0, "named_move": "Elevated hand-post leg pummel to inside position", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "Seated, opponent double underhooks and elevates from knees", "end_occupancy": "neutral", "end_position": "Dual inside leg position", "technique_steps": "1. Start from knees, opponent seated with double underhooks and elevating you.\n2. Retract both feet toward each other and toward your buttocks.\n3. Separate feet slightly.\n4. Turn body and pummel one foot inside the opponent's foot.\n5. Place that foot safely on the floor and extend the leg to hold inside position on one side.\n6. As the opponent locks his foot into your hip, pummel the second foot through as a hook to take inside position on the other side.\n7. Finish with both legs in inside position, ready to attack legs or pass.", "main_ideas": "Retract feet first. Pummel one foot inside. Pummel the second foot through.", "source_time_ranges": []}, {"id": "74d6f8d305b8", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Connection Drills", "chapter_start": 3234.0, "named_move": "Connection Drills (two-on-one scoot to inside position)", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "neutral", "start_position": "seated*", "end_occupancy": "top", "end_position": "outside-ashi*", "technique_steps": "1. Start seated with your knees inside your partner's knees, holding a two-on-one leg grip. 2. Keep hands on the leg grip and do not put them on the floor. 3. Use the feet to draw the hips in toward the opponent by scooting the buttocks hip to hip. 4. Kick through to establish inside position. 5. Move inward to a tight Arumi Ashi Garami, with the elbow over the partner's ankle and the ankle and knee connected. 6. Hold the connection while the partner walks backward on hands and rolls in both directions, testing that the legs, not the hands, maintain it.", "main_ideas": "Connect with your legs, not your hands. Scoot hips hip to hip toward the opponent. Close the knee to ankle and keep the connection through movement.", "source_time_ranges": []}, {"id": "dc1ed9936e27", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Penetration Drills", "chapter_start": 3485.0, "named_move": "Double leg penetration drill", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "neutral", "end_position": "Ashi Garami connection", "technique_steps": "1. Stand in front of standing partner with feet apart, hands away from hips. 2. Make a double leg position with wrists deep, snaking around calf muscles, rounded body. 3. Use the feet to pull the body forward past the partner's ankle line while hands only prevent backward steps. 4. Hips penetrate past the ankle line to reach partner's hips. 5. Throw legs up to Ashi Garami so knees catch with partner's knee inside the knee line, hands freed.", "main_ideas": "Penetrate past the ankle line. Pull with your feet, not your arms. Round your body and snake your wrists to hold the legs.", "source_time_ranges": []}, {"id": "daaf3f38fd21", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Gravity Drills", "chapter_start": 3853.0, "named_move": "Arumi Ashi Garami gravity drill", "ruleset": "both*", "move_type": "drill*", "start_occupancy": "neutral", "start_position": "standing*", "end_occupancy": "bottom", "end_position": "ashi-garami*", "technique_steps": "1. Start standing in a square stance facing the training partner. 2. Penetrate past the partner's ankle line. 3. Come up into Arumi Ashi Garami with the legs binding the partner's leg. 4. Release the hands and hold the position with the legs alone against gravity. 5. Keep a rounded spine and let the partner go down, going up with your head staying over his knee. 6. Repeat for high repetitions with hands released.", "main_ideas": "Bind the leg with your legs, not your arms. Keep a rounded rocking-chair spine. Keep your head over his knee when he goes down.", "source_time_ranges": []}, {"id": "4bd24c4c2188", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Gravity Drills 2", "chapter_start": 4148.0, "named_move": "Gravity Drill (face-away, supine start)", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "leg-drag-position*", "end_occupancy": "top", "end_position": "saddle*", "technique_steps": "1. Start supine with the opponent in an artificial squared-out position, both hands on the opponent's legs, facing the opposite direction from the previous drill.\n2. Pull the body up to develop a rounded, rocking-chair-shaped spine.\n3. Split the legs so one foot goes in the middle and one goes outside.\n4. Hook the inside foot's shoelaces onto the training partner's hamstring just below the buttocks to form an anchor.\n5. Fix the anchor and pull the body weight around behind the opponent using the two hands and the anchor foot.\n6. Use the outside leg as a wedge around behind the opponent's body, scissoring: one leg pushes the thigh, the other pulls the calf.\n7. Place the outside foot on the training partner's hip and square back up.\n8. Repeat on the other side, placing the other shoelace as the new anchor and wedging the outside leg around, moving side to side.\n9. Break down by pushing the knee into the partner's hip while keeping the head over the partner's knee to maintain connection on the landing.", "main_ideas": "Keep a rounded, rocking-chair spine. Anchor the inside foot on the hamstring below the buttocks. Scissor the legs to wedge around the opponent with no hands. Keep your head over the opponent's knee to hold the connection.", "source_time_ranges": []}, {"id": "3b8722635103", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Gravity Drills 3 Rolling", "chapter_start": 4460.0, "named_move": "Rolling Gravity Drill", "ruleset": "*", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "neutral", "end_position": "standing", "technique_steps": "1. Stand facing the partner at roughly 45 degrees, partner standing square with hands away from hips.\n2. Reach in wrist-deep on the partner's knee, not fingers, keeping the spine rounded.\n3. Transition from one grip to a double grip on the knee.\n4. Pull the legs up on the rounded spine, with one leg inside and one outside.\n5. Hook the shin/shoelaces onto the partner's hamstring.\n6. Pull the body around the corner into scissored legs: one leg pushing the far thigh, one pulling the near calf.\n7. Exert outward force and keep the head over the partner's knee to complete the connection.", "main_ideas": "Reach with a rounded spine. Use the legs to form the connection so the hands are free. Keep the head over the knee.", "source_time_ranges": []}, {"id": "f0bb4303044b", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Recovering Knee Line", "chapter_start": 4663.0, "named_move": "Inside scoop knee-line recovery", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "top", "start_position": "Ashi-garami*", "end_occupancy": "top", "end_position": "Ashi-garami*", "technique_steps": "1. From Ashi-garami, feel the opponent's knee drifting away from the knee-line. 2. Punch in and scoop elbow-deep around the opponent's knee, locking the hand around the leg to form a wedge under the knee. 3. Catch the wedge with the second hand. 4. When the opponent pulls away, plant the feet on the floor against the pull. 5. Draw the opponent back inside the knee-line with the scoot grip. 6. Relock the Ashi-garami, turn the thumb down to facilitate drawing the leg, and limp the arm out.", "main_ideas": "Scoop elbow-deep under the knee. Plant your feet and pull him back. Relock and turn the thumb down.", "source_time_ranges": []}, {"id": "4be4a2546b38", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Recovering Knee Line", "chapter_start": 4663.0, "named_move": "Head-follow two-on-one knee-line recovery", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "top", "start_position": "Ashi-garami*", "end_occupancy": "top", "end_position": "Ashi-garami*", "technique_steps": "1. From Ashi-garami, feel the knee-line slipping as the opponent moves away. 2. Sit forward and move the head to chase the opponent's knee. 3. Cup a two-on-one grip on the opponent's leg. 4. As the opponent pulls away, pull yourself to him rather than pulling him to you. 5. Bring the legs back into position to re-establish a firm Ashi-garami and the knee-line.", "main_ideas": "Head chases the knee. Two-on-one grip. Pull yourself to him.", "source_time_ranges": []}, {"id": "5d5d2ea7ee12", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Recovering Knee Line", "chapter_start": 4663.0, "named_move": "Recline-drag knee-line recovery in cross Ashi-garami", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "top", "start_position": "Ashi-garami*", "end_occupancy": "top", "end_position": "Ashi-garami*", "technique_steps": "1. From cross ankle-lock Ashi, feel the knee-line slipping as the opponent escapes. 2. Punch in elbow-deep and grab your own thigh to add a wedge inside the opponent's knee. 3. Recline backwards to drag the opponent rapidly back inside the knee-line. 4. Limp the arm out to re-establish control of the knee-line.", "main_ideas": "Punch in elbow-deep. Grab your own thigh. Recline back to drag him in.", "source_time_ranges": []}, {"id": "e77ad64ec9c0", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E02 - Leg Locks - Enter the System.mp4", "chapter_title": "Recovering Knee Line", "chapter_start": 4663.0, "named_move": "Primary leg knee-line recovery", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "top", "start_position": "Ashi-garami*", "end_occupancy": "top", "end_position": "Ashi-garami*", "technique_steps": "1. When the opponent escapes the primary leg, punch in and go elbow-deep. 2. Grab your own thigh, putting an extra wedge inside the opponent's knee. 3. Recline backwards to drag the opponent well back inside the knee-line. 4. Renew attacks from the recovered position.", "main_ideas": "Punch in elbow-deep. Grab your own thigh for a wedge. Recline back to drag him in.", "source_time_ranges": []}, {"id": "2af8e6cb7bbe", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Single Leg Ashi", "chapter_start": 103.0, "named_move": "Single Leg Ashi Garami Knockdown", "ruleset": "both", "move_type": "takedown", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "bottom", "end_position": "half-guard", "technique_steps": "1. From a standard ashi garami on the opponent's leg with knees pointing outward, grip own buttock or place a hand on own stomach. 2. Place the inside foot on the far (opponent's left) buttock in the straight buttock position, with knee and ankle aligned. 3. Pull upward with the legs (not push) so hips rise and weight loads onto the opponent's far heel, staggering them back. 4. Turn the knees in a curve over the opponent's thigh, driving the opponent down to a hip on the mat. 5. Keep head forward over the opponent's knee for tight connection as they hit the floor.", "main_ideas": "Pull, don't push, to load the far heel. Put the inside foot on the far buttock to stop the hop. Turn everything over the thigh and drive them to the hip.", "source_time_ranges": []}, {"id": "c2ddb4e206f5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "double Leg Ashi", "chapter_start": 427.0, "named_move": "Double Leg Ashi Breakdown", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "top", "start_position": "ashigarami*", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. Hold a standard or reverse ashigarami with head forward over the training partner's knee. 2. When the opponent peels inside knee and outside foot apart, switch from straight buttock to cross buttock. 3. Bump the opponent forward so his hands go toward the mat. 4. Reach across and score the second leg. 5. Re-throw the legs back the way they came, or switch to an ashigarami on the other leg, or pommel and come up to a single leg ashi on the other side, knocking the opponent down to a hip.", "main_ideas": "Switch to cross buttock when the lock starts to fail. Score the second leg to stop the hop. Knock the opponent down to a hip before breaking.", "source_time_ranges": []}, {"id": "c7f7d26ac15e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Inside Leg Breakdowns", "chapter_start": 619.0, "named_move": "X-guard to hip break and transfer into ashigarami", "ruleset": "no-gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "x-guard", "end_occupancy": "top", "end_position": "ashigarami*", "technique_steps": "1. Start in X-guard with inside control and shins inside the opponent's legs.\n2. Tilt knees to one side to bring the opponent's hands to the floor and off-balance him forward.\n3. Drop a foot and tilt knees to the other side to break him backwards to a hip.\n4. Pommel the foot to the inside position.\n5. Sit up so your head goes over the training partner's knee, push off both legs, post on the floor, and slide the knee around the corner into ashigarami position.", "main_ideas": "Use X-guard tension to break the opponent to a hip. Pommel your foot inside and post around the corner into ashigarami.", "source_time_ranges": []}, {"id": "cb76f722334e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Inside Leg Breakdowns", "chapter_start": 619.0, "named_move": "Shin guard sweep to ashigarami", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "shin-to-shin*", "end_occupancy": "top", "end_position": "ashigarami*", "technique_steps": "1. From inside position with the feet, bring the hand across and pommel the second leg in so both shins are inside the opponent's knees.\n2. Lift the opponent's body off the mat and drop him to the floor.\n3. Settle into ashigarami on either side from the hip-down position.", "main_ideas": "Pommel both shins inside the knees, lift and drop the opponent to the hip, and palm in the legs.", "source_time_ranges": []}, {"id": "e1f7fdfe4e08", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Cross Ashi", "chapter_start": 972.0, "named_move": "Cross ashi hip break", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "cross-ashi-garami*", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. From cross ashi-garami, hold the training partner's secondary leg. 2. When the opponent turns away and lifts hips, keep the secondary leg grip. 3. Post a hand on the floor and turn your knee outward against the opponent's hips, driving them back to the mat. 4. If they are too strong to rotate back, rotate across in the opposite direction and roll through the opponent to return them to the mat.", "main_ideas": "Drive force across the opponent's hips, not into their hands.\nPost and turn the knee out against the hips.\nIf rotation fails, roll through the other way.", "source_time_ranges": []}, {"id": "5be3184ea4d9", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Lifting Method", "chapter_start": 1334.0, "named_move": "Lifting Method", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "straight-ashi-garami", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. In straight ashi-garami with the opponent's foot flat on the mat, place your elbow directly on the knuckle line of the opponent's toes.\n2. Line your forearm up with the opponent's foot, not the shin.\n3. Keep your head over the foot to load weight onto the leg and limit space for movement.\n4. Lift the heel with a palm lift or wrist lift, getting your wrist under the heel.\n5. Once the heel is exposed, rotate the elbow back to keep it exposed.\n6. Connect your hands and enter the heel hook.", "main_ideas": "Place your elbow on the toe-knuckle line and line your forearm with the foot. Lift the heel with your palm or wrist. Keep it exposed by rotating the elbow back before connecting your hands.", "source_time_ranges": []}, {"id": "f7b0260dbd34", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Lifting Method", "chapter_start": 1334.0, "named_move": "Lifting Method Cross Ashi", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "cross-ashi-garami", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "", "main_ideas": "", "source_time_ranges": []}, {"id": "4347bec11ced", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Lifting Method Cross Ashi", "chapter_start": 1707.0, "named_move": "Lifting Method Cross Ashi", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "neutral*", "start_position": "cross-ashi-garami*", "end_occupancy": "top", "end_position": "heel-hook-breaking-position*", "technique_steps": "1. From cross ashi-garami, place the elbow on the opponent's leg at the line of the knuckles of the toes. 2. Line the forearm up with the training partner's foot. 3. Get a hand on the lower leg and lift the heel higher than the wrist. 4. Rotate the elbow back to sweep the hand into a strong breaking position, with the forearm blocking heel slippage as the hands lock.", "main_ideas": "Place the elbow at the knuckle line of the toes. Lift the heel above the wrist. Sweep the elbow back to lock the breaking position.", "source_time_ranges": []}, {"id": "a5313a291fab", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "centerline Method", "chapter_start": 1859.0, "named_move": "Centerline Method", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top", "start_position": "straight-ashigarami*", "end_occupancy": "top", "end_position": "heel-exposure*", "technique_steps": "1. Start in a classic or rumi ashigarami with your foot placed on your training partner's hip.\n2. Shift your hips outward, turning your knees across your training partner's centerline.\n3. As the hip shift lifts his heel off the mat and turns it outward, pass your foot across the centerline to cement the position.\n4. Get your wrist underneath, with your forearm lined up with his foot, and lock in a wing.", "main_ideas": "Shift your hips outward to turn your knees across the centerline.\nPass your foot across the centerline to hold the heel out.\nGet the wrist underneath before the exposure disappears.", "source_time_ranges": []}, {"id": "c64279bf82d7", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Tilting Method", "chapter_start": 2004.0, "named_move": "Tilting Method", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "cross-ashi", "end_occupancy": "neutral", "end_position": "heel-hook", "technique_steps": "1. From cross-ashi, get your wrist underneath the opponent's knee, elbow just inside the knuckles of the toe line.\n2. Pass your foot through underneath the opponent's knee and set a drive leg with the sole of your foot close to their crotch.\n3. Tilt back against the opponent's natural direction, bringing your hips under them.\n4. Lift and tilt the opponent across to the other side, exposing the heel.", "main_ideas": "Get the wrist under and drive your hips under the knee. Tilt against their natural direction to expose the heel. Lock the figure-of-four when the heel is exposed.", "source_time_ranges": []}, {"id": "112b3f2191cf", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "negating Resistance Intro", "chapter_start": 2139.0, "named_move": "Pommel and switch to opposite leg from Arimi Ashigarami", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "Arimi Ashigarami on training partner's left leg", "end_occupancy": "top", "end_position": "Arimi Ashigarami on opposite leg", "technique_steps": "1. Hold Arimi Ashigarami on the left leg from top.\n2. As the opponent hops across and the Ashigarami opens, keep the drive leg held in place.\n3. Pommel through with the opposite hand and switch direction.\n4. Catch the second leg at the knee and lock Arimi Ashigarami on the opposite side.", "main_ideas": "Catch the second leg before the first lock is lost. Time the opposite hand to pommel through. Keep the drive leg anchored.", "source_time_ranges": []}, {"id": "fccacd3a5a56", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "negating Resistance Intro", "chapter_start": 2139.0, "named_move": "Arimi Ashigarami to outside Ashigarami on opposite leg", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "Arimi Ashigarami", "end_occupancy": "top", "end_position": "outside Ashigarami on opposite leg", "technique_steps": "1. Lose the Arimi Ashigarami as the opponent goes over the top.\n2. Switch the inside leg and pass feet across.\n3. Lock the outside Ashigarami on the opposite leg while keeping knees to the inside.\n4. Apply breaking pressure from the outside Ashigarami.", "main_ideas": "Keep knees pointing the same direction through the switch. Pass the feet across to set the outside lock.", "source_time_ranges": []}, {"id": "a26a6d53995c", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "negating Resistance Intro", "chapter_start": 2139.0, "named_move": "Arimi Ashigarami to cross Ashigarami via cross buttock", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "Arimi Ashigarami", "end_occupancy": "top", "end_position": "cross Ashigarami", "technique_steps": "1. Opponent stacks forward and separates foot and knee.\n2. Place the foot on the training partner's right buttock.\n3. Bump the opponent forward so the hands come to the mat.\n4. Take a cross frame, kick the free leg through, lift the hips overhead and drop into cross Ashigarami.", "main_ideas": "Use the foot on the buttock to bump forward. Drop the hips into the cross Ashigarami.", "source_time_ranges": []}, {"id": "1d750bd0b184", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Follow Through", "chapter_start": 3245.0, "named_move": "Heel Hook", "ruleset": "both*", "move_type": "submission", "start_occupancy": "neutral*", "start_position": "Heel hook entry from the leg entanglement shown in the chapter", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Lock up the opponent's leg with the heel hook grip, setting the conditions of the break with the upper body and leg position first. 2. Maximize tension in the leg through the ankle and knee without committing the hips. 3. Once the opponent is on the point of tapping, drive the hips through the target as the final element of the follow through. 4. Continue moving through the target with the hips rather than stopping at the breaking point, producing a heel hook finish.", "main_ideas": "Set the conditions first, finish with the hips. Go long through the point of a break. Do not stop at the breaking point.", "source_time_ranges": []}, {"id": "e480b5bacfa6", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Slack Removal", "chapter_start": 3544.0, "named_move": "Slack removal on the heel hook", "ruleset": "both*", "move_type": "submission*", "start_occupancy": "top*", "start_position": "outside-ashi", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Establish contact with the training partner's heel and get underneath it with the forearm. 2. Reach the elbow back so the forearm moves out of line with the lower leg and into line with the partner's foot. 3. Place the ashigarami so the body rides over the own hand and the head begins to straighten and move around the corner. 4. Use forearm and finger tendon movement, without locking the hands or driving the hips, to apply breaking pressure until the partner must tap.", "main_ideas": "Remove slack before breaking. Align the forearm with the foot. Control the break with precise positioning, not force.", "source_time_ranges": []}, {"id": "5012492d5ba5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Slack Removal", "chapter_start": 3544.0, "named_move": "One-handed slack removal drill", "ruleset": "both*", "move_type": "submission*", "start_occupancy": "top*", "start_position": "outside-ashi", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Start from an outside ashigarami. 2. Work the forearm into position relative to the foot. 3. Move the head inside the foot. 4. Use only the movement of the forearm tendons and fingers to create breaking pressure on the leg.", "main_ideas": "Train the feel for slack. Use single-hand movement to find the break point.", "source_time_ranges": []}, {"id": "39c6faceaac1", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Outside Heel Hook", "chapter_start": 4285.0, "named_move": "Outside Heel Hook", "ruleset": "both*", "move_type": "submission", "start_occupancy": "top*", "start_position": "outside-ashi", "end_occupancy": "", "end_position": "heel-hook*", "technique_steps": "1. Start in outside ashi-garami with both feet on the outside of the opponent's legs, locked feet or half triangle.\n2. Follow the opponent's rotation through 360 degrees, keeping control.\n3. Bring the elbow back close to the torso so the opponent's knuckle line of the toes sits in the elbow.\n4. Point the foot across the body and keep the head moving in the same direction as the opponent's lower leg.\n5. Settle on the side, propped on the elbow, with knees pushing down against the opponent's knee to create contrary forces.\n6. Lift the heel to create breaking pressure, removing all slack through head position.\n7. Break the heel hook.", "main_ideas": "Close your elbows to transmit force efficiently. Follow the opponent through every rotation until you break. Lift the heel and drive contrary knee pressure to finish.", "source_time_ranges": []}, {"id": "80f3abf66e24", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Inside Heel Hook", "chapter_start": 4722.0, "named_move": "Inside Heel Hook Single Shoulder Finish", "ruleset": "both*", "move_type": "submission", "start_occupancy": "top*", "start_position": "Inside heel hook entry with forearm aligned to the foot*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Align forearm with the training partner's foot, not the lower leg, to prevent heel slippage. 2. Lock a full Sankaku underneath the training partner's legs. 3. Drive the shoulder down toward the mat to pin the foot. 4. Drive hips forward so they come well up off the floor, putting body weight over the leg. 5. Finish by letting the hips follow the pinned foot to apply breaking pressure.", "main_ideas": "Pin the foot with the shoulder. Follow with the hips. Keep the forearm on the foot, not the shin.", "source_time_ranges": []}, {"id": "6d02c565fd72", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Inside Heel Hook", "chapter_start": 4722.0, "named_move": "Inside Heel Hook Flat Back Finish", "ruleset": "both*", "move_type": "submission", "start_occupancy": "top*", "start_position": "Inside heel hook entry with forearm aligned to the foot*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Align forearm with the training partner's foot. 2. Bring the support hand to the hook hand rather than bringing the hook hand forward, keeping the wrist in the optimal breaking position. 3. Roll both shoulders back toward the floor so the back is flat. 4. Lock the Sankaku with both feet pressuring downward. 5. Drive the hips up and feet down, pointing the elbow toward the training partner's crotch to finish.", "main_ideas": "Roll both shoulders to the mat. Point the elbow at the crotch. Keep the support hand on the hook hand.", "source_time_ranges": []}, {"id": "7486b3eb5e19", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E03 - Leg Locks - Enter the System.mp4", "chapter_title": "Inside Heel Hook", "chapter_start": 4722.0, "named_move": "Inside Heel Hook Outside Single Shoulder Finish", "ruleset": "both*", "move_type": "submission", "start_occupancy": "top*", "start_position": "Inside heel hook after opponent or self-tilt inverts the body*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. When the training partner steps over or is tilted over, point yourself onto the outside shoulder while the opponent is inverted and you still face the ceiling. 2. Press both feet into the side of the training partner's body. 3. Lift the pelvis off the mat. 4. Point the elbow directly at the training partner's hips to apply breaking pressure through rotation.", "main_ideas": "Point onto the outside shoulder. Drive the pelvis off the mat. Aim the elbow at the hips.", "source_time_ranges": []}, {"id": "28cacc58f67c", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Shared Spiral Problem", "chapter_start": 146.0, "named_move": "Single ashigarami against the shared spiral", "ruleset": "both*", "move_type": "submission*", "start_occupancy": "top", "start_position": "straight-ashigarami*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Establish straight ashigarami control. 2. When the opponent begins turning with the heel hook spiral, set the ashigarami against that turn rather than with it. 3. Maintain the single ashigarami as the opponent is forced to give up the escape and the heel hook finishes.", "main_ideas": "Set your ashigarami against the opponent's turn. Use the simple single-ashigarami method against lower-skilled opponents. Do not let the control force match the escape direction.", "source_time_ranges": []}, {"id": "827f968ea22a", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Single Ashi Solution", "chapter_start": 432.0, "named_move": "Single Ashigurami Heel Hook", "ruleset": "both*", "move_type": "submission", "start_occupancy": "neutral*", "start_position": "Arumi Ashigurami on training partner", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Lock up a basic Arumi Ashigurami on the training partner and gain control of the heel. 2. Line the forearm up with the training partner's leg. 3. Lift the pelvis off the mat, sliding the inside leg over the partner's thigh so the knee pushes into the thigh. 4. Keep the knees pointing opposite the heel-hook direction (contrary forces). 5. Commit body weight and form a straight line. 6. If the partner rolls, keep feet in position and keep hips elevated so the second roll is difficult. 7. Lift up on the heel so the knees push against the heel hook for the break.", "main_ideas": "Keep knees opposite the heel hook. Lift the hips off the mat. Commit weight into a straight line and break upward through the heel.", "source_time_ranges": []}, {"id": "c526fe59ffa5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Multiple Ashi Solution", "chapter_start": 703.0, "named_move": "Arimi Ashigarami", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top*", "start_position": "single-leg-x*", "end_occupancy": "top*", "end_position": "saddle*", "technique_steps": "1. Start with the opponent's leg controlled between your legs in a straight ashigarami entry position. 2. Scissor your legs so they close in a shoelace configuration. 3. Lock knee and ankle together with the shoelace closed. 4. Place your weight over the training partner's ankle so that a movement away is felt immediately. 5. Maintain the connection so that any rotation out of the lock is met by staying on the training partner.", "main_ideas": "Close the shoelace and lock knee and ankle together. Put your weight over the ankle. Stay connected to every rotation.", "source_time_ranges": []}, {"id": "6fae5ecdcb52", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Exposing The Heel", "chapter_start": 974.0, "named_move": "Heel exposure from straight ashigarami via inside ashi", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "standing", "end_occupancy": "top", "end_position": "straight-ashigarami*", "technique_steps": "1. From arimi ashigarami entry and connection, keep the elbow propped and do not unweight the inside leg or drop to the shoulder.\n2. Place the foot on the training partner's hip and shift hips to the outside.\n3. Pass the foot across the center line, with the calf over the center of the partner's quadricep, to lift the heel off the mat.\n4. Hold the reaping action across the center line so the partner cannot turn back in and slip the heel.\n5. Finish with the heel exposed and ready for the next phase of heel hooking.", "main_ideas": "Switch ashigarami rather than digging for the heel. Shift hips outward to lift the heel. Keep the foot across the center line to prevent slipping.", "source_time_ranges": []}, {"id": "69f029545402", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Negating Resistance", "chapter_start": 1177.0, "named_move": "Far Hip Ashigurami", "ruleset": "no-gi*", "move_type": "submission*", "start_occupancy": "neutral*", "start_position": "outside-ashi*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. From an inside ashigurami with the opponent's heel already controlled, take the inside leg out and lock a figure-four across the opponent's far hip. 2. Keep the foot hidden in the hip so a figure-four toe hold counter is unavailable. 3. Point the knee down toward the mat so both knees share the same direction. 4. Keep the heel back-heeled in and apply breaking pressure as the opponent runs or drags, maintaining the knee line until the heel hook is finished.", "main_ideas": "Hide your foot in the far hip. Point your knee at the mat with your opponent. Keep the heel back-heeled and the knee line locked.", "source_time_ranges": []}, {"id": "abadf8f97969", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Breaking", "chapter_start": 1612.0, "named_move": "Straight Ashigarami Heel Hook Sequence", "ruleset": "both*", "move_type": "submission", "start_occupancy": "neutral*", "start_position": "arumi ashigarami*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Connect and control the opponent's knee inside your knee line from arumi ashigarami. 2. Turn across the training partner's leg into inside ashigarami to lock up and expose the heel. 3. Rock a sankaku over the far hip and back-heel to tighten the grip; point your knee in the same direction as the opponent's knee. 4. Keep hands locked on shoulders and apply breaking pressure. 5. As the opponent turns, transition legs to the outside of the hips into outside ashigarami and back-heel to pull hips in, finishing the heel hook.", "main_ideas": "Connect with arumi ashigarami before exposing the heel. Lock your hands down on your shoulders. Roll across your shoulders at the same pace as your opponent. Finish from outside ashigarami.", "source_time_ranges": []}, {"id": "5e49c8f2ec67", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Cycles of Inside Outside Dominance", "chapter_start": 2203.0, "named_move": "Straight ashigarami heel hook (simplified finish)", "ruleset": "no-gi*", "move_type": "submission", "start_occupancy": "top*", "start_position": "outside-ashi*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Establish a straight ashigarami with the inside leg between the opponent's legs and the knee pointing outward, inside leg dominant on top of the thigh.\n2. If the heel is already available, apply breaking pressure by scissoring the inside leg across the opponent's thigh.\n3. Finish with the heel hook using inside leg pressure to break the opponent's heel.", "main_ideas": "Use inside leg dominance to break the heel.\nScissor the inside leg across the thigh for breaking pressure.\nThis simplified finish works when the heel is already exposed.", "source_time_ranges": []}, {"id": "fb809159c779", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Cycles of Inside Outside Dominance", "chapter_start": 2203.0, "named_move": "Outside leg reap to expose heel in straight ashigarami", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top*", "start_position": "outside-ashi*", "end_occupancy": "top*", "end_position": "outside-ashi*", "technique_steps": "1. From straight ashigarami in inside leg dominance, place the outside foot on the opponent's hip.\n2. Use a reaping action with the outside leg, pushing across the thigh muscle, to switch dominance to the outside leg.\n3. The reap exposes the opponent's heel and hip.", "main_ideas": "Switch to outside leg dominance to expose the heel.\nPlace the foot on the hip and reap across the thigh.\nReturn to inside leg dominance to break once the heel is exposed.", "source_time_ranges": []}, {"id": "bcc4c57018a5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "Stopping The Spiral", "chapter_start": 2584.0, "named_move": "Stopping the spiral from outside ashigarami", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top", "start_position": "outside-ashi", "end_occupancy": "top", "end_position": "outside-ashi", "technique_steps": "1. Start from an arimi ashigarami and transfer to an inside position so outside leg dominance exposes the heel. 2. Lock up over the training partner's hip and share the spiral while maintaining movement with his escapes. 3. Cycle from outside to inside leg dominance across your body. 4. Point your knees opposite to the opponent's spiral direction. 5. Lift hips off the floor into a straight line so weight is over his leg and he is static, then apply breaking force.", "main_ideas": "Share the spiral only to prevent escape. Stop the spiral by pointing your knees against it. Lift your hips off the floor so weight sits over the leg.", "source_time_ranges": []}, {"id": "2ff278a88730", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "CONTROL SPEED OF THE SPIRAL", "chapter_start": 2926.0, "named_move": "Double Rumi Ashigarami to Outside Ashigarami Heel Hook", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "butterfly-guard", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Enter a Rumi Ashigarami with the shoelaces of the foot on the opposite leg at the hamstring, controlling both legs (double trouble). 2. Turn the knees to expose the heel and get a grip. 3. Keep the left foot underneath the opponent's far knee as a sticky hook behind his knee, actively pressing the shoelaces into the back of the leg. 4. Use the sticky hook to dominate the speed of the opponent's spiral, slowing and stopping his rotation. 5. Point the knees down to create contrary forces while the hook goes the other way, so he is jammed in place. 6. Raise the hips off the floor and hommel the foot over the top of the leg to move into a closed outside Ashigarami wedge. 7. Lift the heel off the mat to finish the heel hook.", "main_ideas": "Keep both legs controlled. Dominate the spiral with a sticky hook. Finish in a closed wedge.", "source_time_ranges": []}, {"id": "38b4d05624b4", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E04 - Leg Locks - Enter the System.mp4", "chapter_title": "CONTROL SPEED OF THE SPIRAL", "chapter_start": 2926.0, "named_move": "Far Hip Ashigarami to Outside Ashigarami Heel Hook", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "butterfly-guard", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Enter a Rumi Ashigarami to establish connection. 2. Expose the heel by bringing the foot across to the inside and getting a grip. 3. Lock a far hip Ashigarami, taking the inside leg over the opponent's hip and locking the figure-four. 4. Point the knee down to negate resistance so that when he moves away you follow. 5. Transition over the leg into an outside Ashigarami, placing weight over his leg so that his spiral cannot continue. 6. Apply the heel hook from the outside Ashigarami finishing position.", "main_ideas": "Lock the far hip to follow his spiral. Transition to outside Ashigarami to stop him. Finish with weight over the leg.", "source_time_ranges": []}, {"id": "5f88cea1625f", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "double leg approach - ankle lace ashi", "chapter_start": 1588.0, "named_move": "Ankle lace ashi garami", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "leg-drag-position", "end_occupancy": "neutral", "end_position": "outside-ashi", "technique_steps": "1. From cross ashi garami, when the opponent begins to turn out away from you, straighten your leg.\n2. Reach and snatch the opponent's leg with a two-on-one grip, one hand above the knee and one below.\n3. Grip wrist-deep with both wrists bent at least 90 degrees, four fingers locking into the knee tendon area.\n4. Draw everything back and lock the grip up with an Achilles hold, holding the leg in place without applying heat.\n5. Finish with the ankles laced together, controlling the opponent's direction and preventing turnout.", "main_ideas": "Grip the knee tendon wrist-deep, not superficially.\nLock the ankles together before going for any submission.\nStop movement first; do not fish for a heel hook.", "source_time_ranges": []}, {"id": "38a91d4ec2b3", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "managing the release", "chapter_start": 1929.0, "named_move": "Achilles lock from ankle-lace ashigurami (no-release heel hook setup)", "ruleset": "no-gi*", "move_type": "submission", "start_occupancy": "top*", "start_position": "cross-ashigurami*", "end_occupancy": "", "end_position": "heel-hook*", "technique_steps": "1. From cross ashigurami, lift the opponent's secondary leg. 2. Pass the free arm inside and underneath your own arm, going below the ankle, not in front. 3. Lock a reverse figure-four grip at the ankle so the thumb sits near the ankle, not halfway down the shin. 4. Lock up and point the elbow toward the opponent's hips, bringing one leg down on top of the other to create breaking pressure on the anterior tibialis tendon. 5. If the opponent fights the hands, turn the wrists; as the secondary leg pops out, transition into the inside heel hook.", "main_ideas": "Do not release the leg; attack it. Feed the free hand below the ankle. Point the elbow toward the hips, not across the leg.", "source_time_ranges": []}, {"id": "b60d7687c552", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "alternative achilles grip", "chapter_start": 2206.0, "named_move": "Alternative Achilles grip", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "cross-ashi-garami*", "end_occupancy": "", "end_position": "straight-ankle-lock", "technique_steps": "1. From cross ashi garami with the ankle lace in place, tie up the opponent's secondary leg so it cannot turn out when released. 2. Feed one hand through the opponent's knee; control the ankle with the other hand. 3. Bring the elbow back in line with the ankle, shrug the hips back, and thrust the elbow forward. 4. Seat the opponent's heel on the attacker's floating rib so he cannot push the boot through. 5. Grip own bicep and shoulder in a figure-four variation, point the elbow at the opponent's hips, and drive into the Achilles lock targeting the anterior tibialis.", "main_ideas": "Keep the secondary leg tied, don't release it. Seat the heel on your floating rib to stop the boot. Drive the elbow into the anterior tibialis.", "source_time_ranges": []}, {"id": "c1029abbf7b5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "alternative achilles grip", "chapter_start": 2206.0, "named_move": "Achilles lock to inside heel hook transition", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "cross-ashi-garami*", "end_occupancy": "top", "end_position": "inside-heel-hook*", "technique_steps": "1. From the Achilles grip position, when the opponent fights the hands and pulls his foot free, fall straight back. 2. Transfer to the inside heel hook with the lock still in. 3. Position the heel for a breaking angle. 4. Pull on the outside of the heel as the opponent turns it up to secure the catch.", "main_ideas": "Fall back as the opponent pulls free. Transfer straight into the inside heel hook.", "source_time_ranges": []}, {"id": "a3a2ec4f1e12", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "double heel hook attack", "chapter_start": 2498.0, "named_move": "Double heel hook attack", "ruleset": "no-gi*", "move_type": "submission", "start_occupancy": "top*", "start_position": "cross ashi garami", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. From cross ashi garami, control the secondary leg and wrist-deep grip the training partner's calf. 2. Turn the wrist down to expose the heel of the secondary leg. 3. Punch through and bite on the heel with a conventional heel hook grip. 4. Lift and feed into a reverse figure four grip, tighter. 5. Place the elbow over the primary foot, pointing the elbow at the opponent's hips to apply breaking pressure. 6. Lock the senkaku with the legs, clearing the primary heel. 7. Switch to an inside heel hook on the secondary leg.", "main_ideas": "Keep the secondary leg controlled and expose its heel. Point the elbow at the hips, not across the body. Finish by switching to the inside heel hook.", "source_time_ranges": []}, {"id": "b4ccdade748e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "lace leg (creating dilemma)", "chapter_start": 2706.0, "named_move": "Lace leg break", "ruleset": "no-gi", "move_type": "submission", "start_occupancy": "top", "start_position": "outside-ashi", "end_occupancy": "", "end_position": "kneebar", "technique_steps": "1. Start from ankle lace (ashi-garami) with the opponent's secondary leg controlled.\n2. Control the training partner's knee and punch through on the leg so the arm controlling the secondary ankle goes between the ankles and elbow-deep around the Achilles tendon.\n3. Line the hand up with the opponent's toes to keep leverage.\n4. Bring the free hand to the breaking hand (not the reverse), cross wrists, and lock up.\n5. Bring hands to the heart so the pressure travels across the centerline.\n6. Pitch over onto the side, push with both feet, and pull one leg across the other to break.", "main_ideas": "Punch through and lock up with the hand at the end of the lever.\nBring the free hand to the breaking hand, never the reverse.\nKeep the hand lined up with the toes to hold leverage.", "source_time_ranges": []}, {"id": "0b8f705d1d75", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "splitter hand", "chapter_start": 2879.0, "named_move": "Splitter hand to inside heel hook", "ruleset": "both*", "move_type": "submission*", "start_occupancy": "top*", "start_position": "cross-ashi-garami*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. From cross ashi garami, hold the opponent's secondary leg at the heel. 2. Lift the secondary leg and insert a forearm between his two legs as a splitter hand. 3. Free arm goes around the corner and locks up the heel. 4. Opponent's turnout now breaks his own leg; add force to double back for the heel hook finish.", "main_ideas": "Lock the heel before you release the leg. Split the legs with a forearm, then lock the heel. Let the turnout break the leg.", "source_time_ranges": []}, {"id": "a5ebf7ff80f6", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "splitter hand", "chapter_start": 2879.0, "named_move": "Knee-push secondary leg release", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top*", "start_position": "cross-ashi-garami*", "end_occupancy": "top*", "end_position": "heel-hook*", "technique_steps": "1. With the heel hooked, pitch over to your side as the opponent thrusts his foot into your armpit. 2. Place your inside knee just inside his knee, repositioned from hip to knee. 3. Push with the knee into his knee so the secondary leg pops out while the primary leg stays in place. 4. Fall back into a strong break from the heel hook.", "main_ideas": "Use your legs, not your arms, to remove the secondary leg. Keep the primary leg locked while the knee pushes the secondary leg out.", "source_time_ranges": []}, {"id": "836f97075cf2", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "elbow slicer", "chapter_start": 3230.0, "named_move": "elbow slicer", "ruleset": "both*", "move_type": "submission*", "start_occupancy": "top*", "start_position": "cross-ashi-garami*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Start in cross ashi garami with a splitter hand in place and the opponent's secondary leg pushing into your armpit to run interference. 2. Grab hold of the training partner's ankle. 3. Lean over the opponent's ankles with body weight and slice the elbow between his two ankles, locking his ankles apart. 4. Arch back and split the legs. 5. Expose the inside heel by positioning the forearm on the floor beside the heel. 6. Lift the heel over the forearm hurdle so the shoelace reaches the armpit, with hands long and knees pointing back. Finish: inside heel hook in perfect breaking position.", "main_ideas": "Use body weight, not elbow strength, to slice between the ankles. Lift the heel over the forearm like a hurdle. Keep hands long and knees pointing back to finish the break.", "source_time_ranges": []}, {"id": "99f0a74c433e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "over under method", "chapter_start": 3437.0, "named_move": "Over-under method", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top", "start_position": "cross ashi-garami*", "end_occupancy": "top", "end_position": "inside heel hook*", "technique_steps": "1. Start in cross ashi-garami with the opponent's secondary leg tied up. 2. Place a hand on the training partner's calf and bring his two knees together. 3. Close your own knees around his legs and drop your elbow tight to his ankles to create a wedge. 4. Move your head away, form the hand into a knife, and spear it through the ankles to lock the shoelaces to your neck, creating a six-point wedge. 5. Plant a foot and use cross-buttock to tilt the opponent over, exposing the heel. 6. Lock inside senkaku with your legs and reach back to secure the heel for the inside heel hook finish.", "main_ideas": "Bind the legs together with knees and elbow before attacking. Build the six-point wedge with the spearing hand and shoelaces. Tilt the opponent to expose the heel, then finish the inside heel hook.", "source_time_ranges": []}, {"id": "42c1453445f4", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "double elbow", "chapter_start": 3721.0, "named_move": "Double elbow method", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "ashi-garami", "end_occupancy": "top", "end_position": "heel-hook", "technique_steps": "1. Start laced in ankle lace ashi garami. 2. Build a five-point wedge around the opponent's legs and hips: one hip, one hand, one elbow, with the other hip and hand as the remaining points. 3. Convert to a six-point wedge by making a knife hand through the opponent's ankles and locking it up, using the neck as the sixth point. 4. If the opponent hides his foot, point one elbow at him, then pass the second elbow underneath, hold the heel, and pull the shoelaces into the armpit so both elbows point at him. 5. Transition from the double elbow position straight into the inside heel hook for a maximal break.", "main_ideas": "Build the wedge before you move. Lock both elbows on the heel. Finish the inside heel hook straight from the double elbow.", "source_time_ranges": []}, {"id": "eb7a8d8e214d", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "double cross method", "chapter_start": 3861.0, "named_move": "double cross method", "ruleset": "no-gi*", "move_type": "submission*", "start_occupancy": "top", "start_position": "cross ashi-garami", "end_occupancy": "", "end_position": "inside heel hook", "technique_steps": "1. From cross ashi-garami with the opponent's primary leg controlled, take a hold of the leg and move to a five-point wedge (two knees, hips, hand, elbow).\n2. Perform a knife hand through to convert the five-point wedge into a six-point wedge.\n3. Move the head backward past the foot, drawing the opponent's secondary leg across the centerline so both legs cross in opposite directions.\n4. Take a V-grip on the opponent's Achilles tendon and wedge the top leg over both ankles to hold them in place.\n5. Sit up and forward with a forward shift so the head matches the opponent's head height.\n6. Reach back with the thumb to secure the heel, using both legs to draw the opponent back so the knee line goes back.\n7. Go over the top, release, and finish the inside heel hook.", "main_ideas": "Lock up the secondary leg so both legs cross the centerline.\nSit up and forward to reach the heel.\nIf the primary leg is lost, the secondary leg becomes the new primary.", "source_time_ranges": []}, {"id": "fbe97298c721", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E05 - Leg Locks - Enter the System.mp4", "chapter_title": "controlling shared spiral", "chapter_start": 4066.0, "named_move": "Inside heel hook from cross ashigurami (single-leg control, controlling the turnout)", "ruleset": "both*", "move_type": "submission", "start_occupancy": "neutral", "start_position": "cross ashigurami", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. From cross ashigurami with one leg controlled, sit up and forward to access the heel.\n2. Place the hand around the opponent's knee, fingers through the knee tendons, wrist bent about 90 degrees as a handbrake.\n3. Close the elbow and place it on the inside to add an elbow break.\n4. As the opponent turns, put your head on the floor as a head post to block their roll.\n5. Hook your free foot inside the opponent's near knee to further slow their turn.\n6. Turn faster than the opponent so your head ends up inside their legs and you access the heel.\n7. Lock the inside heel hook as you emerge on the outside of the roll and break.", "main_ideas": "Slow the opponent's turnout instead of outpacing it. Brake the knee with your hand and elbow. Post your head and hook your foot to win head position.", "source_time_ranges": []}, {"id": "4bfb4bbbbdb8", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Untying Legs", "chapter_start": 289.0, "named_move": "Untying the triangle from reverse ashi garami", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "reverse ashi garami", "end_occupancy": "neutral", "end_position": "outside-ashi", "technique_steps": "1. Start in reverse ashi garami with the opponent's triangle locked. 2. Seize the knee and ankle and draw the opponent's legs up onto the hip to tighten the knot. 3. Wedge with both knees pointing the same direction around the opponent's legs. 4. Place the middle of one hand on the first knuckle of the opponent's smallest toe; the other hand goes underneath to seize the heel at the other end of the lever. 5. Pull one foot toward the opponent's own knee, keeping the arms crossed over the crossed legs. 6. As the knot unties, straighten the second leg, keeping the feet separated. 7. Keep the elbow inside the opponent's shin to prevent re-tying. Finish with two untied legs and the opponent's legs controlled.", "main_ideas": "Tighten the knot before you untie it. Wedge with your knees together and pull the foot toward the opponent's own knee. Keep your elbow inside the shin to prevent re-tying.", "source_time_ranges": []}, {"id": "d561defea590", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Leg Roll", "chapter_start": 618.0, "named_move": "Double Leg Roll", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "reverse-de-la-riva*", "end_occupancy": "top", "end_position": "rear-naked-choke*", "technique_steps": "1. From reverse ashi-rami with legs untied and wedged, drop the knee that sits between the opponent's legs to the mat. 2. Move your head outside the opponent's foot first, to win the race for the foot. 3. Take the foot off the leg and hug it to your chest while rolling across the opponent's legs. 4. Lock a sankaku (triangle) around both of the opponent's legs, with the primary leg pinned by bodyweight and the other held at the end of the lever. 5. Finish the roll to the shoulder and hold the sankaku, leaving the extended leg ready to attack.", "main_ideas": "Drop the knee to the mat first. Win head position before releasing the foot. Lock sankaku around both legs to control both.", "source_time_ranges": []}, {"id": "674751236e5e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Figure Four Toe Hold", "chapter_start": 947.0, "named_move": "Double Leg Roll to Figure Four Toe Hold", "ruleset": "no-gi*", "move_type": "submission", "start_occupancy": "top", "start_position": "reverse-ashi-garami*", "end_occupancy": "", "end_position": "toe-hold", "technique_steps": "1. Start on top in reverse ashi garami, with a knee on the floor and the opponent's heel secured. 2. Secure the heel and come up to the toe line, locking the grip with the elbow in the middle and untying the legs. 3. Put a knee on the floor, catch the heel, and come down to the mat with a senkaku. 4. Use the hand to block the secondary leg while the elbow controls it, and reach around inside to grab your own thigh or the opponent's calf. 5. Lock a half triangle (semi-senkaku) at the calf, keeping the elbow pulled back toward yourself. 6. Arch forward with the knee extending and the pelvis driving in to finish the toe hold. Alternative: from the double leg roll, lock the figure four around the leg, block the second arm, pass the arm around and drive the elbow behind you, extending the knee and driving the pelvis forward into the lat knee bar, or place the shoelaces on your shoulder and drive forward with both hands.", "main_ideas": "Keep the elbow back toward yourself. Start every finish from the knee and drive the pelvis forward. Use the double leg roll to gain stability and separate the legs before finishing.", "source_time_ranges": []}, {"id": "b75d298e9d29", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Dilemma Attack", "chapter_start": 1166.0, "named_move": "Figure Four Toe Hold Dilemma Setup", "ruleset": "no-gi", "move_type": "submission", "start_occupancy": "top", "start_position": "reverse-ashi-garami*", "end_occupancy": "", "end_position": "heel-hook*", "technique_steps": "1. Tighten the lock and hike opponent's legs close to you from reverse ashi garami. 2. Grab one foot, reach across and grab the other, drawing that foot over and inside your knee so it is wedged and supported by your knee. 3. Wedge the leg from above with your right arm, armpit and tricep over his leg. 4. Take one foot around the corner as the hand extends, drop the knee to the mat in a controlled fashion, establishing the breaking position. 5. If he does not react, lock the figure four toe hold: grip the toes with your knuckles over the smallest toe, point toes toward his tailbone, push to take slack, then pull with the right elbow.", "main_ideas": "Wedge both sides of the leg before dropping. Push the toes in, then pull with the elbow. Protect the knee and keep the body controlled on the way down.", "source_time_ranges": []}, {"id": "1c9c115e962b", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Dilemma Attack", "chapter_start": 1166.0, "named_move": "Lat Knee Bar Switch from Figure Four Toe Hold", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "top", "start_position": "figure-four-toe-hold*", "end_occupancy": "", "end_position": "kneebar*", "technique_steps": "1. From the figure four toe hold, when opponent reacts by pushing with his other foot, grab the heel of the primary leg. 2. Pass your arm through and around, placing a hand on the calf. 3. Retract the elbow behind you to take the slack out of the knee. 4. Keep your knee and back heel pointed forward so the opponent cannot turn the knee inside your ashi garami. 5. Drive forward for breaking pressure on the leg.", "main_ideas": "Retract the elbow to remove slack. Keep the knee pointed forward. Drive forward once the leg is controlled.", "source_time_ranges": []}, {"id": "2cdd6284399e", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Figure Four toe Hold Primary Leg", "chapter_start": 1597.0, "named_move": "Figure Four Toe Hold (from reverse ashi garami, primary leg)", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "reverse-ashi-garami*", "end_occupancy": "", "end_position": "toe-hold", "technique_steps": "1. From reverse ashi garami with both legs controlled, tighten the knot and keep the knee down for stability. 2. Untie the training partner's legs to expose the primary leg. 3. Release the secondary leg and catch the foot with the first middle knuckle of the hand on the smallest toe's knuckle line, covering the knuckle line without grabbing toes or shoelaces. 4. Bring the head close to the foot so both hands connect easily. 5. Lock the hands, keep the elbow down by the heel and ankle, and walk the ankles across to the far side. 6. Bring the foot's toes into the hip pocket and place the body in front of the shoelaces. 7. Sweep the elbow down to the heel and ankle, keeping the leg sharply bent, and break with the elbow pulling while the knee presses down.", "main_ideas": "Lock in tight and keep the head close to the foot. Pocket the toes into the hip with the body in front of the shoelaces. Drive the elbow down to the heel and break.", "source_time_ranges": []}, {"id": "654033533505", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Figure Four toe Hold Non Optimal Conditions", "chapter_start": 2106.0, "named_move": "Figure Four Toe Hold from Reverse Ashi Garami (non-optimal)", "ruleset": "both*", "move_type": "submission", "start_occupancy": "top", "start_position": "reverse-ashi-garami*", "end_occupancy": "", "end_position": "toe-hold", "technique_steps": "1. From reverse ashi garami, feed the hand underneath the opponent's legs to untie the knot. 2. Come down to a knee to stabilize and lock on the end of the lever. 3. Push the palm on the toes toward the tailbone while the pulling elbow is at the heel line. 4. If the leg extends, move the head toward the foot and keep the chest inside the opponent's knee. 5. Lock up the ankles and lift with the elbow for a pulling finish against the extended leg.", "main_ideas": "Bring your head to the foot when the leg extends. Keep your chest inside the knee. Finish with the pulling elbow, not the push.", "source_time_ranges": []}, {"id": "46b687a9b619", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Figure Four toe Hold Non Optimal Conditions", "chapter_start": 2106.0, "named_move": "Heel Hook from Figure Four Toe Hold Transition", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "reverse-ashi-garami*", "end_occupancy": "", "end_position": "heel-hook*", "technique_steps": "1. When the toe hold is lost to extension, grip the heel with one hand while propped on the elbow. 2. Lift the heel off the floor to protect the back as the opponent moves behind. 3. Put the head inside the opponent's leg and switch position. 4. Tuck, place the shoelaces under the armpit, and lock up the figure four. 5. Finish with a strong heel hook using the elbow pull.", "main_ideas": "Release and catch the heel when the toe hold is gone. Lift the heel to protect your back. Finish with the heel hook.", "source_time_ranges": []}, {"id": "0260f931fa2a", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Transition to Outside Ashi Outside Heel Hook", "chapter_start": 2545.0, "named_move": "Reverse ashigurami to outside ashigurami heel hook", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "reverse-ashigurami*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Start in reverse ashigurami, bottom, with the opponent's legs tied up.\n2. Tighten up, secure the heel that will be attacked, and untie the opponent's legs (foot and elbow inside the shin as the end of the lever).\n3. Gain stability by placing the knee on the mat.\n4. Wrap the bicep around the heel with thumb down (not thumb up) so the wrap fully turns the heel and tension is already present.\n5. Control the descent by posting a hand and going down to an elbow, not the shoulder.\n6. Turn to face the opponent, transitioning to outside ashigurami.\n7. Lock the hands (e.g. figure four, palm to palm, wrist to wrist).\n8. Bring the head over the foot, keeping the head in a straight line, and lift the heel for breaking pressure to finish the heel hook.", "main_ideas": "Secure the heel and untie the legs before anything else.\nWrap thumb down so tension is built before the heel hook starts.\nFall on the same side of the attacked leg, not across the body.", "source_time_ranges": []}, {"id": "175f2e1d168f", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Transition to Cross Ashi Inside Heel Hook", "chapter_start": 2897.0, "named_move": "Transition to Cross Ashigarami Inside Heel Hook", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "reverse ashigarami*", "end_occupancy": "top", "end_position": "cross ashigarami*", "technique_steps": "1. Start perched on top of the training partner in reverse ashigarami, with the right hand securing the heel of the partner's right foot.\n2. Take the left hand across to a grip on the heel and lift the heel over your knee to form a wedge.\n3. Lean forward on the partner, release the heel, go over the top, and double up the wedge.\n4. Go around elbow-deep on the partner's leg and post the second hand on the partner's knee.\n5. Turn your knees in on the partner and sit down, ending in a double treble cross ashigarami control of both legs.", "main_ideas": "Wedge the heel over your knee. Go elbow deep around the ankle. Turn the knees in and sit down into cross ashigarami.", "source_time_ranges": []}, {"id": "48cbb7718583", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Transition to Cross Ashi Inside Heel Hook", "chapter_start": 2897.0, "named_move": "Transition to Inside Sankaku", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "reverse ashigarami*", "end_occupancy": "top", "end_position": "cross ashigarami*", "technique_steps": "1. Start in front of the training partner and reach across the shin to secure the ankle.\n2. Lift the ankle and wedge it with the right knee, keeping the arm close.\n3. Go elbow deep around the ankle and turn in, blocking and wedging the left knee under the partner's left knee.\n4. Lock the partner's legs up and control one leg to set up the inside heel hook or inside sankaku finishes.", "main_ideas": "Lift and wedge the ankle with the knee. Turn in and lock both legs. Control one leg to finish.", "source_time_ranges": []}, {"id": "cd5b8d672617", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Head Position", "chapter_start": 3300.0, "named_move": "Straight ashigarami to outside ashigarami via head-away heel exposure", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "straight-ashigarami*", "end_occupancy": "bottom", "end_position": "outside-ashigarami*", "technique_steps": "1. From bottom, establish a two-on-one grip on the opponent's right leg in reverse ashigarami with the opponent on two knees. 2. When the opponent's head moves away, cover the shoelaces to keep the exposed heel controlled. 3. Extract legs, move to an inside position, and switch to far-hip ashigarami. 4. Apply pressure and roll across the hips into outside ashigarami, reaching the break.", "main_ideas": "Watch the head; when it moves away, the heel is exposed. Cover the shoelaces and transition through the ashigarami family to the break.", "source_time_ranges": []}, {"id": "75e121e42618", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Head Position", "chapter_start": 3300.0, "named_move": "Cross-buttock control with collar tie against head-toward heel plant", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "straight-ashigarami*", "end_occupancy": "bottom", "end_position": "reverse-x-guard*", "technique_steps": "1. When the opponent's head moves toward you and the heel is planted, place the right foot on the right buttock in cross-buttock position. 2. Circle the left arm around the opponent's ankle for control, not for a heel hook. 3. Take a collar tie when available to balance the opponent forward and bring the hands toward the mat. 4. Pommel the second leg inside and transition to reverse X-guard.", "main_ideas": "When the head comes in, go cross-buttock and control the ankle. Use the collar tie to drive the opponent forward into reverse X-guard.", "source_time_ranges": []}, {"id": "a588abed0365", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Head Position", "chapter_start": 3300.0, "named_move": "Reverse X-guard to senkaku", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "reverse-x-guard*", "end_occupancy": "", "end_position": "senkaku*", "technique_steps": "1. From reverse X-guard, get the opponent's hips directly over your head. 2. Punch the legs through and around. 3. Lock the senkaku while dropping the standing partner straight down to the mat. 4. Hold the controlling position.", "main_ideas": "Get the hips overhead first, then punch the legs through and lock the senkaku.", "source_time_ranges": []}, {"id": "4d32bad18ea9", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Opponent Spins Leg Crossover", "chapter_start": 3670.0, "named_move": "Leg crossover on opponent's spin from straight ashi garami", "ruleset": "both*", "move_type": "transition", "start_occupancy": "top", "start_position": "straight ashi garami*", "end_occupancy": "top", "end_position": "cross ashi garami*", "technique_steps": "1. From straight ashi garami (rumi ashi garami), threaten the heel hook. 2. Catch the opponent's legs as he initiates a spin to relieve heel pressure. 3. Hold the heel; as the opponent turns, bring the second hand in and cross the leg over your centerline by switching the foot from the right armpit to the left armpit. 4. Immediately sit up and forward so your head is over the opponent's knee, not supine. 5. Lace the ankle into ashi control to stop a second turn, or, if the leg is missed, generate heel exposure and finish with an inside heel hook.", "main_ideas": "Cross the leg in the middle of his turn. Sit up and forward before completing the crossover. Lace the ankle to stop the second turn.", "source_time_ranges": []}, {"id": "c551dc1555fe", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Static Crossover", "chapter_start": 3946.0, "named_move": "Static crossover from double Achilles ashi garami to senkaku-inside crossover", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "straight ashi garami*", "end_occupancy": "top", "end_position": "outside-ashi*", "technique_steps": "1. Start in straight ashi garami holding both opponent legs with a double Achilles grip. 2. Separate the opponent's legs and switch across into a senkaku with your feet on the inside. 3. Bring the hand down to the opponent's ankle and limp the first arm out so the hand goes over the ankle. 4. Bridge off the inside foot down to the floor with the right knee pointing at the opponent's hip so yanking the leg out is difficult. 5. Bridge off the left foot and let the opponent's foot rise toward your chest. 6. As the foot rises, move up and forward so your head is directly over his knee, passing your feet through to the second leg. 7. Sit forward toward the second knee to either control the secondary leg or attack the primary leg. 8. Alternatively, pass the legs to the inside, limp the first arm out and lock the senkaku, limp the second arm out, and bring the knees back with the knee pointed at the hip. 9. Open the shoelaces to create space, then bridge to lift and elevate the foot, and cross the foot over with two hands to secure the secondary leg.", "main_ideas": "Separate and switch into an inside senkaku. Bridge the foot up to the chest. Move head over the knee before crossing over.", "source_time_ranges": []}, {"id": "3bcb9bb01101", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Spin Leg To Cross Ashi", "chapter_start": 4188.0, "named_move": "Spin Leg To Cross Ashi", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "straight-ashi*", "end_occupancy": "neutral", "end_position": "cross-ashi*", "technique_steps": "1. From a straight ashigarami position with the opponent moving away and the knee line lost, pop up. 2. Fold your foot underneath the opponent's legs and take a scoop grip on his leg. 3. Perform an elbow-escape-like motion to bring your knee inside the opponent's legs. 4. Bring your chest over the opponent's thigh, hand to the floor. 5. In one motion spin and place wedges around the opponent's knee, moving from inside his legs to outside, converting to cross ashigarami.", "main_ideas": "Spin around the leg when the knee line is lost.\nCrowd the chest forward over the thigh.\nWedge immediately after the turn.", "source_time_ranges": []}, {"id": "af132dc88db5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Spin Leg To Reverse Ashi", "chapter_start": 4414.0, "named_move": "Spin Leg To Reverse Ashi", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "cross-ashi-garami", "end_occupancy": "neutral", "end_position": "reverse-ashi-garami", "technique_steps": "1. Start in cross ashigurami with the training partner, facing him. 2. Take your leg through and scoop the partner's other leg. 3. Shoot your arm across the partner's body. 4. Draw your left foot back. 5. Hop across the partner's body and come up into reverse ashigurami, facing away from him.", "main_ideas": "Spin the leg out of cross ashigurami when hand fighting stalls you. Hop across and come up facing away. Use your back to block his hands.", "source_time_ranges": []}, {"id": "17572a8aabd3", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E06 - Leg Locks - Enter the System.mp4", "chapter_title": "Rolling Transition From straight to Cross Ashi", "chapter_start": 4616.0, "named_move": "Rolling transition from straight ashi to cross ashi", "ruleset": "both*", "move_type": "transition", "start_occupancy": "top", "start_position": "outside-ashi", "end_occupancy": "top", "end_position": "outside-ashi*", "technique_steps": "1. From outside ashi garami, hold the opponent's heel with the hand (no Achilles lock) after losing the heel grip.\n2. As the opponent comes forward with head over your head, keep hold of the ankle.\n3. Slide the free hand under the opponent's armpit.\n4. Push off the bottom leg to bring the body up onto the knees.\n5. Position the head inside the opponent's knee.\n6. Roll through and come out the back door into cross ashi garami.\n7. Tie up the secondary leg or attack the primary leg.", "main_ideas": "Hold the ankle; don't chase the lost heel. Roll under the armpit and head inside the knee. Come out the back door into cross ashi.", "source_time_ranges": []}, {"id": "45fb5cb96b86", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Sliding Ashi", "chapter_start": 0, "named_move": "Ashi slide from distance", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "top", "end_position": "ashi-garami", "technique_steps": "1. Start standing at distance facing the training partner with no tie-up.\n2. Level change down, posting one hand on the floor to measure the level change and set the right angle.\n3. Catch the training partner behind the knee with the hand that is on the mat.\n4. In one motion, pull the partner forward and slide the hip past the line of the partner's ankles.\n5. Throw the legs to finish with the hips past the ankle line in ashi-garami control.", "main_ideas": "Level change and touch the floor to set your angle.\nCatch behind the knee and slide your hip past the ankle line.\nFinish with your hips past the partner's ankles in ashi control.", "source_time_ranges": []}, {"id": "53e3880d1de5", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Colloring Elbow", "chapter_start": 298.0, "named_move": "Collar-elbow square-up into ashigarami entry", "ruleset": "gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "neutral", "end_position": "straight-ashigarami*", "technique_steps": "1. Start standing in a collar-and-elbow tie, taking the inside position on the bicep with collar and elbow grips while the opponent holds two elbows.\n2. Initiate contact as the opponent reaches, moving onto the inside, with the second hand coming up.\n3. Move away from the opponent's far leg and pull to square them up.\n4. Step your foot inside the opponent's foot, falling across their center line rather than along it.\n5. Let the foot go out and fall into ashigarami.\n6. Expose the heel and roll through into straight ashigarami attacking position.", "main_ideas": "Win the inside position before you pull. Square them up by moving off their far leg. Fall across their center line, never backwards.", "source_time_ranges": []}, {"id": "9e49f0f9b150", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Leg Entry", "chapter_start": 511.0, "named_move": "Double leg entry to outside Ashi Garami", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "bottom", "end_position": "outside-ashi", "technique_steps": "1. From standing with bicep ties on the opponent, square him up with a pull.\n2. Level change, sending his arms past.\n3. If the double leg is failing and the legs start moving back, put the inside leg up instead of the outside leg.\n4. Fall across the training partner's body with the head toward the ankle, exposing the heel.\n5. Roll through to outside Ashi Garami for the finish.", "main_ideas": "Put the inside leg up when losing the double leg.\nFall toward the ankle to expose the heel.\nRoll through into outside Ashi Garami.", "source_time_ranges": []}, {"id": "4c0a498b7227", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Single Leg Entry", "chapter_start": 706.0, "named_move": "High Single Leg to Ashi Garami Entry", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "bottom", "end_position": "outside-ashi", "technique_steps": "1. Stand in neutral with inside tie. 2. Step away from the target leg, keeping own foot close to it, and pull the leg forward. 3. Run to the second hip, dropping level. 4. Come up and wedge around the training partner's leg. 5. If the partner whizzers and places a foot outside, execute shoulder pommel: drive the shoulder into the quadricep to bump the partner forward until the whizzing hand reaches the floor. 6. Post own hand to the floor with fingers matching the partner's, hook the knee with the shoelaces of the right foot. 7. Roll through into outside ashi garami.", "main_ideas": "Step away and pull the leg in, not step your own leg back.\nRun to the second hip and wedge tight around the leg.\nShoulder pommel the quad to drop the whizzing hand, then roll into ashi.", "source_time_ranges": []}, {"id": "ea0381a38ee9", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Front Headlock", "chapter_start": 967.0, "named_move": "Front headlock to leg entry", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. Start standing with an inside tie on the training partner.\n2. Fake the legs to make the partner bring the legs back, which brings the head down.\n3. Snap the head down and lock up a front headlock.\n4. As the partner straightens up, knee drive through wrist-deep toward the opposite foot.\n5. Drive through the front headlock and drive the partner's hip down to the mat.\n6. Post, lift, and penetrate the knee all the way through; cup the partner's knee.\n7. Sit across into the crossface.", "main_ideas": "Fake the legs to bring the head down. Lock the front headlock as the partner straightens. Knee drive through to the opposite foot and drive the hip to the mat.", "source_time_ranges": []}, {"id": "cdce67115156", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Front Headlock", "chapter_start": 967.0, "named_move": "Front headlock to leg entry (over the top)", "ruleset": "both", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "top", "end_position": "standing", "technique_steps": "1. Start standing with an inside tie on the training partner.\n2. Start an action finishing the legs to get the head to come down.\n3. Go over the top and bang the head, ending in a front headlock.\n4. Drive through toward the opposite ankle.\n5. Put the second foot up and drive the partner down to the mat.\n6. Switch knees and penetrate to the legs.\n7. Catch a post and step the legs in to reach an attacking position.", "main_ideas": "Finish the legs to bring the head down. Go over the top to bang the head into a front headlock. Drive the partner to the mat and step in for an attacking position.", "source_time_ranges": []}, {"id": "a12aa61dec91", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Arm Drag", "chapter_start": 1105.0, "named_move": "Arm Drag to Ashigarami Entry", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "neutral", "end_position": "single-leg-x*", "technique_steps": "1. Standing, control opponent's wrist with a down grip.\n2. Step in on the opponent and step out with the left foot to get elbow-deep on the opponent's leg.\n3. Fall with the head to the outside while the left knee sweeps inside the opponent's knee.\n4. Sit and pull the opponent onto you to achieve a strong attacking angle on the leg.", "main_ideas": "Drag the wrist to clear the arm and head. Step in and out to get elbow-deep on the leg. Fall outside and sweep the knee to set the attack.", "source_time_ranges": []}, {"id": "b5b5e5cded3a", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "4 Point Breakdown", "chapter_start": 1292.0, "named_move": "Standing rear body lock to four point to cross ashi garami", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "top", "end_position": "outside-ashi", "technique_steps": "1. Start standing behind opponent in a rear body lock.\n2. Place your knee in front of opponent's knee.\n3. Shunt opponent's hands down to the mat, reaching a four point position.\n4. Move around to the opposite side of his body, dropping your knee inside.\n5. Put your shoulder under his hamstring and touch his triceps with your own triceps.\n6. Flick him over onto his side.\n7. Step to the legs, post a hand on the floor, and step into cross ashi garami.", "main_ideas": "Drop your knee in front of his to shunt him down. Get inside his hamstring with your shoulder. Flick him over and step into cross ashi.", "source_time_ranges": []}, {"id": "2ed757887a95", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "4 Point Breakdown", "chapter_start": 1292.0, "named_move": "Standing rear body lock to four point to leg entry (shelving)", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "standing", "end_occupancy": "top", "end_position": "outside-ashi", "technique_steps": "1. Start standing behind opponent in a rear body lock after a duck under, arm drag, or slide-by.\n2. Place your knee in front and shunt him down to a four point position.\n3. Move around to the other side, dropping your knee as you come in.\n4. Lift his leg so it shelves onto your leg.\n5. Pry on his tricep with your hand and bring him over in that direction.\n6. Step to the opposite leg, cover the knee, and post the floor.\n7. Pop over the top to reach attacking position.", "main_ideas": "Shunt him to four point with your knee. Shelve his leg on yours. Cover the knee and pop over the top.", "source_time_ranges": []}, {"id": "3498cc406cee", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Intro Ground position", "chapter_start": 1442.0, "named_move": "Double elevator", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "bottom", "end_position": "outside-ashi*", "technique_steps": "1. From butterfly guard, seated, establish double triceps (or collar ties or double underhooks) and drive the opponent's hands over your shoulders to the mat so he carries his own weight.\n2. Bring your head forward and scoop your center of gravity under his using your feet.\n3. Elevate him: switch from flared elbows (pulling grip) to narrowed elbows (pushing grip) and drive his hips directly over your head.\n4. Once his hips are over your head, take your hand across your body, turn 90 degrees, and place your knee into his hip to create angle.\n5. Finish: if his head moves away, go to straight ashigarami; if his head moves toward you, go to cross ashigarami.", "main_ideas": "Get his hands over your shoulders to the floor. Scoop your center under his and elevate his hips over your head. Turn the angle with your knee and attack the leg that opens.", "source_time_ranges": []}, {"id": "dbfb78ec3e55", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Bottom Single Elevator", "chapter_start": 1715.0, "named_move": "Single Leg Elevator from Bottom Half Guard", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "half-guard", "end_occupancy": "top", "end_position": "ashigarami*", "technique_steps": "1. From bottom half guard with opponent tripoding up and knees off the floor, scissor the legs around the opponent's knees rather than leaving them apart. 2. Stand on the opponent's Achilles tendon with the left foot to resist his kick-out. 3. Pommel the right foot inside and take a butterfly hook, initially locking the second leg over. 4. Plant the foot briefly and shift hips underneath the opponent. 5. Elevate him with one leg to the outside over the right shoulder. 6. Take a double thumb post, clear the head, and drive the inside knee to create distance. 7. Expose the heel and rotate through into the braking position.", "main_ideas": "Scissor the legs around the knees, not apart.\nElevate to the outside with the inside knee creating the distance.\nExpose the heel and rotate to the braking position.", "source_time_ranges": []}, {"id": "d58c668051a7", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Crossed Feet Single Elevator", "chapter_start": 1977.0, "named_move": "Crossed Feet Single Elevator", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "butterfly-guard", "end_occupancy": "top", "end_position": "leg-drag-position*", "technique_steps": "1. From butterfly guard, step one leg forward into a staggered stance facing the training partner.\n2. Take a tight waist grip all the way around the training partner while controlling the far hip.\n3. Place the second foot across and outside the training partner's leg, ideally above the knee.\n4. Put one hand on the floor; keep the other in the tight waist grip.\n5. Connect the knee to the training partner's far hip.\n6. Lock up, slide the hand from the floor inside the training partner's legs, and pull the knee into the hip while lying back, so the opponent floats on the knees.\n7. Transfer the waist-grip hand into a cross arm frame on the other side.\n8. Lift and turn beyond 90 degrees to set up a double leg catch that drops the training partner.\n9. Lock up and finish from the resulting position.", "main_ideas": "Stagger your stance to own the waist and far hip. Cross your feet and lie back to float your partner on your knees. Turn past 90 degrees and drop them into the finish.", "source_time_ranges": []}, {"id": "f71889e464ab", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Inversion", "chapter_start": 2207.0, "named_move": "Inversion Leg Lock Entry", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom", "start_position": "half-guard*", "end_occupancy": "top", "end_position": "half-guard*", "technique_steps": "1. Start on bottom with opponent on two knees who has taken inside position with one foot, leaving you only one foot inside.\n2. Catch the training partner at the Achilles tendon, controlling the outside of the thigh with the shinbone and placing the leg on the inside.\n3. Throw in a reverse de la Riva hook and go deep in front of the opponent's ankle.\n4. Invert and spin, gripping and taking the knee to an inside position underneath the partner.\n5. Drive forward with both legs to move the opponent's weight progressively onto their hands, forcing them to hold balance.\n6. Place the foot on the opponent's centerline.\n7. Rise, punch the other knee straight through, and shift the hips so the legs drop in.\n8. Finish in a winning position on the floor, locking the figure of four where applicable.", "main_ideas": "Use inversion when inside position is stolen. Catch the Achilles, invert, and drive weight onto the hands. Punch the knee through and drop into a winning position.", "source_time_ranges": []}, {"id": "ce8bf30537da", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Knee Shield Inversion", "chapter_start": 2482.0, "named_move": "Knee Shield Inversion to Cross Ashigarami", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "half-guard", "end_occupancy": "top", "end_position": "leg-drag-position", "technique_steps": "1. From bottom half guard with a low, shallow knee shield in the pocket of the hip, forearm frame across the shoulder line, and hand on the bicep. 2. Remove the bicep hand and scoop grip inside the opponent's legs, slipping the shoulder-line hand underneath the armpit. 3. Bring the knee across to the far hip and pivot around the hip by inverting and turning the foot. 4. Turn the head inside the opponent's knees. 5. Lock both hands around the opponent's leg in a body-lock-like grip. 6. Use the outside leg in a pendulum action to take the opponent's hips over your head. 7. Switch to senkaku with the legs and land cross ashigarami.", "main_ideas": "Keep the knee shield low and shallow. Turn your head inside the knees. Lock the leg with both arms and pendulum the hips over.", "source_time_ranges": []}, {"id": "622b133c4f33", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Knee Shield to X Guard", "chapter_start": 2739.0, "named_move": "Knee shield to X guard", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "half-guard", "end_occupancy": "bottom", "end_position": "x-guard", "technique_steps": "1. Start bottom in half guard with a knee shield in place. 2. If you cannot invert under the opponent, transition the knee shield leg into X guard. 3. Use the pressure of the X guard to move to the desired position.", "main_ideas": "Use X guard pressure when inversion is not available. Transition from the knee shield quickly.", "source_time_ranges": ["0.00-0.00"]}, {"id": "99ec6ab382c9", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Knee Shield to X Guard", "chapter_start": 2739.0, "named_move": "Butterfly hook to reverse X guard", "ruleset": "no-gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "half-guard", "end_occupancy": "bottom", "end_position": "reverse-x-guard", "technique_steps": "1. Start bottom in half guard, opponent scooped and resisting by sitting back. 2. Bring the knee shield leg inward and place the foot as a butterfly hook. 3. Lock hands with the opponent's leg controlled above the knee and below the elbow, so the hands prevent backward movement. 4. Extend the bottom leg off the floor to shift the hips under the center of gravity, displacing the opponent's structure by turning hips and knees. 5. Slide the foot up and enter reverse X guard, controlling the whole leg. 6. Elevate to put the opponent into position for the inside heel hook.", "main_ideas": "Shift your hips, don't pull with arms. Use the legs to move the opponent's center of gravity. Finish by entering reverse X guard and elevating for the inside heel hook.", "source_time_ranges": ["0.00-0.00"]}, {"id": "6d8380229ab0", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Hook Sweep to Reverse X Guard", "chapter_start": 2983.0, "named_move": "Hook Sweep to Reverse X Guard", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "reverse-x-guard*", "technique_steps": "1. Start bottom in guard with a tight waist grip and inside control of the opponent's near arm. 2. Attempt a hook sweep (sumi gaeshi); the opponent pommels the hand over your forearm and tripods, so the sweep fails. 3. Take a scoop grip on the opponent's leg with the arm that was underneath the opponent. 4. Plant the foot that was on the floor to the mat, keeping the hand inside as a frame. 5. Transfer the arm from the tight waist to the shoulder and shift the hips from facing one direction to the other, off-balancing the opponent in the opposite direction. 6. Feed the unused drive leg underneath the opponent. 7. Lift to put the opponent's hips directly over your head, arriving in reverse X guard, and kick through to lock the legs.", "main_ideas": "Use the failed sweep as an entry. Scoop the leg and shift hips to off-balance. Feed the leg through into reverse X guard.", "source_time_ranges": []}, {"id": "cda9bd51c8bc", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Arm Drag", "chapter_start": 3272.0, "named_move": "Arm Drag to Leg Entry", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "leg-drag-position", "technique_steps": "1. From bottom with an opponent on two knees in front, secure any wrist control. 2. Initiate the arm drag; the opponent posts a foot and steps up and forward, denying the back. 3. Do not put a foot to the outside or turn toward the back. 4. Go forward elbow-deep on the opponent's leg, combining the upper-body grip with the elbow-deep leg grip. 5. Bring the knee to the inside and place the foot to the opponent's near buttock (cross buttock position). 6. Use the upper-body grip to bring the opponent forward and elevate off the floor, lifting him into the air. 7. Finish in position to lock the figure-four (leg entanglement) and drop him onto the mat.", "main_ideas": "Drag, but do not chase the back if he posts. Go elbow-deep on the leg. Elevate with the cross buttock foot and upper-body grip.", "source_time_ranges": []}, {"id": "c7378d0366cf", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Collar and Heel Entry", "chapter_start": 3487.0, "named_move": "Collar and Heel Entry to Leg Lift Drop", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "bottom*", "start_position": "open-guard*", "end_occupancy": "top*", "end_position": "leg-drag-position*", "technique_steps": "1. From bottom seated position, fight hands with the standing or crouching opponent until a collar and heel catch is available.\n2. Catch the opponent's collar and heel in one simultaneous motion, leaning forward into the hand fight.\n3. Pull the body into the opponent with the foot, placing the foot in the cross buttock position.\n4. Draw the opponent inward and bring the second foot through.\n5. Lift the opponent with both feet engaged, bringing the hips over the head and releasing the head down.\n6. Drop the opponent into the attacking position.", "main_ideas": "Catch the collar and heel in one motion. Pull in with the foot to the cross buttock. Lift with both feet and drop into position.", "source_time_ranges": []}, {"id": "8d80c5a356e8", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E07 - Leg Locks - Enter the System.mp4", "chapter_title": "Shoelace Breakdown", "chapter_start": 3737.0, "named_move": "Shoelace Breakdown", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "x-guard", "end_occupancy": "bottom", "end_position": "reverse-x-guard", "technique_steps": "1. From conventional X-guard, bottom, with the top foot of the X placed with its shoelaces on the opponent's shoelaces.\n2. Extend the leg and stand tall to lift the opponent's foot off the mat.\n3. Bring the opponent's foot up toward their buttocks.\n4. Drop the opponent's knee to the mat, moving you from supine to seated.\n5. Switch into reverse X-guard; pull the opponent while throwing your body weight back to the mat to drag their hips over your head.", "main_ideas": "Lift the foot, drop the knee, sit up. Switch to reverse X-guard. Throw your weight back to bring the hips overhead.", "source_time_ranges": []}, {"id": "b770905b79f9", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Sitback", "chapter_start": 0, "named_move": "Straight ashigarami sit back entry", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "open-guard*", "end_occupancy": "top", "end_position": "saddle*", "technique_steps": "1. From top against a supine opponent, grip the heel with one hand. 2. Step in past the opponent's hip line, not the buttocks. 3. Catch the knee with the second hand for a two-on-one grip. 4. Level change so hips are at the height of the opponent's knees. 5. Hold, step up to the hip line, and sit back onto the legs with hips hip-to-hip, creating a barrier against sit-up to top.", "main_ideas": "Penetrate to the hip line. Control the knee with a two-on-one. Drop hips to knee height before you sit back.", "source_time_ranges": []}, {"id": "339810b4e21b", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Sitback", "chapter_start": 0, "named_move": "Cross ashigarami sit back entry", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "open-guard*", "end_occupancy": "top", "end_position": "saddle*", "technique_steps": "1. From top against a supine opponent, enter from outside the legs. 2. Step all the way up to the opponent's hip line. 3. Take a two-on-one grip on the outside of the knee and level change so hips are at knee height. 4. Fall into the sit back while releasing and covering the toes. 5. Pass the foot to the inside and recapture the heel as the leg goes over the top, reaching a position to finish.", "main_ideas": "Enter from outside the legs. Cover the toes as you fall. Capture the heel on the way in.", "source_time_ranges": []}, {"id": "474d3eb5d004", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Inside Out Entry", "chapter_start": 416.0, "named_move": "Inside Out Entry", "ruleset": "no-gi*", "move_type": "transition", "start_occupancy": "top", "start_position": "open-guard", "end_occupancy": "top", "end_position": "leg-drag-position*", "technique_steps": "1. Start standing or kneeling inside the opponent's open guard, scoop-gripping the legs with the opponent supine.\n2. Take a leg control both above and below the knee, similar to the X-guard grip.\n3. Post on the opponent's upper body and pick the foot up, striking the hamstring with the shoelaces so the knee drops to the floor.\n4. Hike the arm up and control the ankle; put the hand to the floor.\n5. Swing the back foot around to touch the opponent's buttocks.\n6. Spin around the opponent's leg and drive the knee in behind the opponent's knee as a wedge.\n7. From the wedge, sit across the secondary leg to reach a winning position.", "main_ideas": "Post on the upper body and drop the knee across the adductors.\nWedge the knee behind the opponent's knee before sitting across.\nAttack the leg when the opponent blocks passing pressure.", "source_time_ranges": []}, {"id": "48c46a031f29", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Outside In Entry", "chapter_start": 590.0, "named_move": "Outside In Entry", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "open-guard", "end_occupancy": "top", "end_position": "outside-ashi*", "technique_steps": "1. From top with the opponent supine, establish a scoop grip on their leg with the lower leg lifted toward your shoulder.\n2. Pin the leg to the floor with your second hand and post on the opponent's chest to come into a tripod.\n3. Step your right foot so the toes rotate from facing the opponent's head to facing away, the leg passing across your chest.\n4. Post on the knee, tilting it toward the floor with fingers behind the hamstring.\n5. Step forward, pop up, and move around the hip line while hugging the leg, falling on the starting side.\n6. Shift the hips out to a two-on-one grip, cover the ankle, and reach the leg-control position.", "main_ideas": "Spin to the inside, not the outside.\nPost on the knee with fingers behind the hamstring.\nFinish on the same side you started.", "source_time_ranges": []}, {"id": "9b5252d47436", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Outside Step In", "chapter_start": 784.0, "named_move": "Outside Step In", "ruleset": "both*", "move_type": "transition*", "start_occupancy": "top", "start_position": "outside-ashi*", "end_occupancy": "top", "end_position": "outside-ashi*", "technique_steps": "1. Start standing over the supine opponent with a grip on his legs (shins, knees, or hip and knee).\n2. Step to the side to guide his legs outward and create an attacking angle; do not stay lined up with him.\n3. Take a hand to the knee so the knee and hand wedge both sides of the leg.\n4. Level change down with hips at the height of his knees, keeping base on the floor.\n5. Step the foot through to an inside position between his legs, or drop the knee in first and pass the foot afterwards.", "main_ideas": "Step off the line to create the angle. Wedge the leg with hand and knee. Level change low and pass the foot inside.", "source_time_ranges": []}, {"id": "eff29f5b3e5c", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Half Guard Entries", "chapter_start": 1043.0, "named_move": "Half Guard Scoot-Grip Entry", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top", "start_position": "half-guard", "end_occupancy": "top", "end_position": "outside-ashi", "technique_steps": "1. From top half guard, when the opponent pummels for an underhook and you are losing that battle, withdraw your elbow and scoop through to take a scoop grip on his upper body underhook.\n2. Punch your hand through to the floor as a post beneath his underhooking arm.\n3. Pop up and place your knee across his hip line, putting weight on him.\n4. Reposition your hand further out and reposition your foot to his buttocks at the centerline.\n5. Turn the corner of his leg and wedge your knee where your wrist is, pinning his leg in place.\n6. Sit with your foot and hand taking the weight, with the knee acting as a wedge.\n7. Choose either to go straight for the heel as a heel hook, or cross to the second ankle with a two-on-one grip to control before heel hooking.", "main_ideas": "Scoop through and post when losing the underhook.\nSlide your knee across his hip line and wedge it at the wrist.\nChoose heel hook or control the second leg before attacking.", "source_time_ranges": []}, {"id": "f10f89588133", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Half Guard Entries", "chapter_start": 1043.0, "named_move": "Half Guard Step-Over Entry", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top", "start_position": "half-guard", "end_occupancy": "top", "end_position": "outside-ashi", "technique_steps": "1. From top half guard with neither player controlling the upper body, reach through and catch the opponent's wrist on the near side.\n2. Sit upright while holding the wrist.\n3. Lift your leg wide and step it over all the way to the opponent's buttocks and lower back on the far side.\n4. Catch the opponent at the heel and unlock his feet, controlling both legs.\n5. Step your foot around the corner and lock.\n6. Use the lifting method to lock up the opponent's legs and fall to the same side already on.\n7. Apply outside ashi-garami and the outside heel hook.", "main_ideas": "Catch the wrist so he cannot grab your leg.\nStep over rather than slide through.\nLift, lock, and fall to the same side.", "source_time_ranges": []}, {"id": "938f43eb467a", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Half Guard Entries", "chapter_start": 1043.0, "named_move": "Half Guard Back Step Entry", "ruleset": "no-gi*", "move_type": "transition*", "start_occupancy": "top", "start_position": "half-guard", "end_occupancy": "top", "end_position": "outside-ashi", "technique_steps": "1. From generic top half guard with the opponent's legs trapping your knee, turn and pop up to free the trapped knee.\n2. Place your left hand on the floor, bring the right hand to the left hand, and reposition the left.\n3. Take your knee and back step, placing it as a wedge behind the opponent's knee.\n4. Pin the opponent's top leg between both of your legs.\n5. Place your foot on the floor and catch the other leg.\n6. Elevate and fall across his body into the attacking position.", "main_ideas": "Free the trapped knee by turning and popping up.\nBack step to wedge behind his knee.\nCatch the second leg and fall across.", "source_time_ranges": []}, {"id": "637195ccc4ae", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Kani Basami", "chapter_start": 1618.0, "named_move": "Kani Basami", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "standing", "end_occupancy": "top", "end_position": "lace-leg ashigarami*", "technique_steps": "1. Stand in front of the seated opponent at toe distance, capturing one of the opponent's wrists or hands on each side with the hands.\n2. Step in, blocking a hand on either side, and get the foot across so weight is placed over the opponent's right-hand side.\n3. Post and push the opponent's hand to the mat so his left knee rises.\n4. Step through, bring the head next to the opponent's head, and capture the ankle.\n5. Back step and level change down so the hips are at the height of the opponent's knees.\n6. Bring the wedge in behind the knee and drop the opponent into lace-leg ashigarami.", "main_ideas": "Off-balance the opponent to make the opposite knee rise. Wedge the leg in while his knee is up. Drop him into lace-leg ashigarami and control from there.", "source_time_ranges": []}, {"id": "38305d2773b8", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Kani Basami", "chapter_start": 1618.0, "named_move": "Kani Basami entry to inside heel hook", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "lace-leg ashigarami*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. From the Kani Basami wedge, thread the leg over the top of the opponent's leg.\n2. Tie up the secondary leg.\n3. Return to a winning position and transition into the inside heel hook series.", "main_ideas": "Thread the leg over, tie up the secondary leg, and return to a winning position. Finish into the inside heel hook series.", "source_time_ranges": []}, {"id": "9f1ea20351a3", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Seated Position", "chapter_start": 1824.0, "named_move": "Heel hook from double seated (two-on-one grip, foot pass across center line)", "ruleset": "both*", "move_type": "submission", "start_occupancy": "neutral", "start_position": "double seated*", "end_occupancy": "", "end_position": "heel-hook", "technique_steps": "1. Sit in double seated with one foot inside each, knees in front of each other.\n2. Break the opponent's grips, pommel to the cross buttock position with both feet together under one leg.\n3. Take a two-on-one grip on the opponent's foot and use your feet to pull your body forward to the opponent's knee line.\n4. Punch through and pass your foot across the center line to expose the heel.\n5. Roll through, track the far hip, rotate, and finish the heel hook.", "main_ideas": "Pommel to cross buttock, not straight buttock.\nKeep the two-on-one grip and move with your feet.\nPass the foot across the center line to expose the heel.", "source_time_ranges": []}, {"id": "4c89f2ef9df6", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Seated Position", "chapter_start": 1824.0, "named_move": "Kani Basami from double seated (pommel transfer, collar tie, heist)", "ruleset": "both*", "move_type": "takedown", "start_occupancy": "neutral", "start_position": "double seated*", "end_occupancy": "top", "end_position": "kesa-gatame*", "technique_steps": "1. Break the opponent's grips and pommel to the inside, switching the first foot across.\n2. Fold the leg underneath the opponent and lean forward with a post hand on the floor and a collar tie.\n3. Heist up to a kneeling position.\n4. Pop up, release the collar, back step and use a hand assist to pull the opponent's knee in.\n5. Finish in Kani Basami on the floor.", "main_ideas": "Fold the leg underneath and lean in with a collar tie.\nHeist to a knee, then back step to pull the knee in.", "source_time_ranges": []}, {"id": "52023ac9ba07", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Seated Position", "chapter_start": 1824.0, "named_move": "Kani Basami from double seated (head post tripod catch)", "ruleset": "both*", "move_type": "takedown", "start_occupancy": "neutral", "start_position": "double seated*", "end_occupancy": "top", "end_position": "kesa-gatame*", "technique_steps": "1. Break grips and pommel to cross buttock with legs folded.\n2. Create an initial threat on the opponent's left leg.\n3. When the opponent lowers knees, head post to the floor and tripod with both hands off weight.\n4. Catch the Kani Basami and sit back into the attacking position.", "main_ideas": "Head post to the floor to tripod.\nLet the head carry the weight so the hands are free to catch the leg.", "source_time_ranges": []}, {"id": "4c67864e900d", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Seated Position", "chapter_start": 1824.0, "named_move": "Level change to Kimura from double seated (wrist catch, roll through)", "ruleset": "both*", "move_type": "transition", "start_occupancy": "neutral", "start_position": "double seated*", "end_occupancy": "top", "end_position": "back-control*", "technique_steps": "1. Break grips, pommel to the inside, fold the leg and pop up on the opponent.\n2. When the opponent brings knees into the chest, catch the opponent's wrist.\n3. Level change and roll through into Kimura territory.\n4. Turn to the opponent's back as they turn in.", "main_ideas": "Catch the wrist when the knees come in.\nLevel change and roll through into the Kimura.", "source_time_ranges": []}, {"id": "402f4575911c", "instructor": "John Danaher", "instructional": "Enter the System by John Danaher - Leglocks", "volume": "Leg Locks by John Danaher - S01E08 - Leg Locks - Enter the System.mp4", "chapter_title": "Double Seated Position", "chapter_start": 1824.0, "named_move": "Guard pass from double seated (pommel, pop up, drive over the top)", "ruleset": "both*", "move_type": "pass", "start_occupancy": "neutral", "start_position": "double seated*", "end_occupancy": "top", "end_position": "side-control*", "technique_steps": "1. Break grips, pommel to the inside, and pop up.\n2. When the opponent shortens the legs, come over the top and pommel the knee in.\n3. Drive through and pass.", "main_ideas": "Pop up and come over the top when the legs shorten.\nDrive through to pass once the knee is in.", "source_time_ranges": []}, {"id": "85f7cb8a09c5", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "Closed Guard Overview", "chapter_start": 0, "named_move": "Overhead sweep", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From bottom closed guard, opponent is standing up in two steps.\n2. As opponent makes the second step and is vulnerable to forward off-balancing, off-balance him forward.\n3. Sweep him over with the overhead motion.\n4. Finish with your hips in top position, arriving in mount.", "main_ideas": "Catch the second step of the stand-up. Off-balance forward. Sweep to mount.", "source_time_ranges": []}, {"id": "8f50eeda1ab5", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "The Six Vulnerabilities - Part 1", "chapter_start": 2187.0, "named_move": "Elbow across the center line to side scissor", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "side-scissor*", "technique_steps": "1. Start in closed guard with hips sitting on the opponent's hips and the opponent's lead elbow controllable.\n2. Take the opponent's elbow past the center line.\n3. Move laterally out to the side, climbing toward the opponent's back, to reach a side scissor with the arm trapped.\n4. Come up on an elbow and keep your head higher than the opponent's head to set up access to the back.", "main_ideas": "Pass the elbow across the center line first.\nMove out to the side as the hips stay on the hips.\nKeep your head above his head.", "source_time_ranges": []}, {"id": "9b7ee294805f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "The Six Vulnerabilities - Part 2", "chapter_start": 2380.0, "named_move": "Top lock", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "armbar", "technique_steps": "1. From bottom closed guard, walk the legs up the spine toward the shoulders.\n2. Lock the legs over the opponent's shoulders and behind the head (top lock), controlling the head and shoulders at the top of the spinal lever.\n3. Keep the posture broken forward and control the head and shoulders.\n4. Shorten the distance to the arm and move into an armlock attack from the top lock.", "main_ideas": "Walk your legs up to the shoulders before attacking. Lock behind the head to control the top of the spine. Use the top lock to set up armlocks.", "source_time_ranges": []}, {"id": "38eb6e1a3016", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "The Six Vulnerabilities - Part 3", "chapter_start": 2544.0, "named_move": "Inside wrist to trap triangle", "ruleset": "both", "move_type": "transition", "start_occupancy": "top", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "technical-mount", "technique_steps": "1. From closed guard, stuff one of the opponent's wrists so your arm controls him from the inside. 2. Place your second hand on his wrist with a thumb block inside his wrist, so he cannot pull the hand inward. 3. Unweight the bottom leg and weight the top leg, then pass one leg around. 4. Lock the feet high behind the opponent's head and close the guard around the head and one arm to finish in a trap triangle.", "main_ideas": "Win the inside wrist position first. Use the thumb block to stop the hand from coming in. Lock the trap triangle high behind the head.", "source_time_ranges": []}, {"id": "bd93eb64de37", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "The Six Vulnerabilities - Part 4", "chapter_start": 2768.0, "named_move": "The Clamp", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "clamp*", "technique_steps": "1. From closed guard, get both (or one) of the opponent's hands down to the mat by getting your hands inside his and bringing him forward. 2. Slide your hips out underneath his arm. 3. Place one knee in front of one shoulder and the other knee behind the other shoulder, isolating the head and one arm from the other arm.", "main_ideas": "Get the hands to the mat. Swim the hips out and clamp. Isolate the arm.", "source_time_ranges": []}, {"id": "306adf985094", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "The Six Vulnerabilities - Part 5", "chapter_start": 3122.0, "named_move": "Knee pull on opponent's second stand-up step", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "closed-guard*", "technique_steps": "1. From closed guard, opponent grips lapels and begins to stand, first leg rising. 2. Wait for the first step and watch the head move off center. 3. As the opponent takes the vulnerable second step, pull the knee down to break their balance. 4. Opponent is brought back down to knees.", "main_ideas": "Wait for the second step. Pull the knee as the head yaws. Break balance and bring them back to knees.", "source_time_ranges": []}, {"id": "cf94b2439da3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E01 - Overview.mp4", "chapter_title": "The Six Vulnerabilities - Part 6", "chapter_start": 3584.0, "named_move": "Ankle scoop to hip drop from closed guard", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, the opponent stands up on posture as the guard player watches for the rise. 2. The guard player scoops a grip inside the opponent's ankle. 3. The guard player clicks the grip and knocks the opponent down onto a hip. 4. With the opponent's hip on the mat, the guard player moves to top hip position and begins sweeping or attacking submissions.", "main_ideas": "Scoop the ankle when the opponent stands up. Knock them down to a hip. Move to top hip position immediately.", "source_time_ranges": []}, {"id": "b1fe5bde608f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Holding And Controlling A Closed Guard", "chapter_start": 1876.0, "named_move": "Knee pull (closed guard kuzushi)", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From closed guard bottom with opponent in front, grip behind the elbows or cross collar behind the neck. 2. Bring knees up toward the opponent's armpits, not down toward the biceps. 3. Pull up and forward first, opening the elbows and breaking posture forward. 4. Keep knees high into the armpits so the pull travels up and then down through the opponent's posture. 5. Hold the broken posture to return the opponent to two knees.", "main_ideas": "Pull with knees into the armpits. Pull up and forward first. Attack posture before anything else.", "source_time_ranges": []}, {"id": "1355b761d2d3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Holding And Controlling A Closed Guard", "chapter_start": 1876.0, "named_move": "Cross collar grip knee pull", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From closed guard bottom with opponent working inside, reach a cross collar grip behind the opponent's neck. 2. Control the end of the spinal lever at the head. 3. As opponent tries to posture up, combine the cross collar grip with a knee pull. 4. Pull up and forward to break posture down and prevent him from achieving upright posture.", "main_ideas": "Control the top of the spinal lever. Combine the cross collar with the knee pull. Keep his posture broken.", "source_time_ranges": []}, {"id": "30147dd6aa93", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Holding And Controlling A Closed Guard", "chapter_start": 1876.0, "named_move": "Sleeve cuff brace hand removal", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. Opponent has a brace hand on the trouser or hip. 2. Grip the wrist of that brace hand with a sleeve cuff grip on top of the wrist. 3. Pull the arm through, either across the body or locked onto the opponent. 4. With the arm controlled, pull in with the legs to break his grip and prevent posturing up.", "main_ideas": "Remove the brace hand early. Grip the wrist from the top. Pull the arm through.", "source_time_ranges": []}, {"id": "5b14925aa031", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Holding And Controlling A Closed Guard", "chapter_start": 1876.0, "named_move": "Elbow grip sit-up and forward break", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. Opponent has two hands on the belt and elbows pressed into your thighs. 2. Sit forward and grip behind the opponent's elbows. 3. Bring knees in toward the chest while opening his elbows outward. 4. Break his posture forward and begin shifting hips to the side to set up controls.", "main_ideas": "Come forward against a weak belt grip. Grip behind the elbows. Break posture forward.", "source_time_ranges": []}, {"id": "dab39d704c35", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Establishing Angle From Closed Guard", "chapter_start": 3744.0, "named_move": "Planted foot in shrimp (angle from closed guard)", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From closed guard bottom with opponent posture broken, shrimp hips out to one side.\n2. Plant one foot close to the opponent's ankle (not out wide, to prevent stepping over into half guard).\n3. Lock feet on the far side of the opponent's body to establish angle.", "main_ideas": "Plant the foot close to the ankle. Shrimp out and lock feet on the far side. Do not post the foot out wide where it can be stepped over.", "source_time_ranges": []}, {"id": "b9372393de35", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Establishing Angle From Closed Guard", "chapter_start": 3744.0, "named_move": "Planted foot on hip angle (from closed guard)", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From closed guard bottom with opponent posture broken, place or replace a foot on the opponent's hip.\n2. Shift hips out to the side, bringing the knee directly behind the opponent's head.\n3. Lock up closed guard with feet on the far side of the body to establish angle.", "main_ideas": "Plant the foot on the hip so the opponent cannot step over. Shift out until the knee is behind the head. Lock up the guard.", "source_time_ranges": []}, {"id": "96c82dda8396", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E02 - Understanding Closed Guard.mp4", "chapter_title": "Establishing Angle From Closed Guard", "chapter_start": 3744.0, "named_move": "Shimmy angle from closed guard", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From closed guard bottom with opponent posture broken by a knee pull, open guard and straighten legs.\n2. Lift hips off the floor and turn the knee into the opponent's hip so feet point upward, then rotate feet to point out to the side.\n3. Lock closed guard on the far side of the opponent with the knee directly behind the head.", "main_ideas": "Shimmy with legs off the floor. Never put a knee or foot down. Lock up with the knee behind the head.", "source_time_ranges": []}, {"id": "07ee35298ee3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "The Side Scissor: Elbow Across The Centerline - Converting a Closed Guard to a Side Scissor", "chapter_start": 0, "named_move": "Closed Guard to Side Scissor (Arm Trap Across Centerline)", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "side-control", "technique_steps": "1. From bottom closed guard, take a cross-cuff grip on the opponent's lead arm (or rear arm if the lead elbow drops). 2. Pull in with the knee and push the trapped arm across the centerline, going in the direction of the opponent's fingers. 3. Break the grip by placing the heel of the hand on the opponent's knuckles, then lock onto the seam that runs down the back of the sleeve. 4. Shift the hips out to the side, keeping the knees pulling toward the back of the opponent's head. 5. Re-lock the feet and finish in the side scissor position, out to the side with the opponent's arm trapped and halfway behind his back.", "main_ideas": "Pull with the legs, not the arms. Break the grip with the heel of the hand and lock the sleeve seam. Shift out and keep the knees high to the back of the head.", "source_time_ranges": []}, {"id": "f28beaeefde6", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "The Subtle Push Pull Dynamic of the Side Scissor Position", "chapter_start": 1562.0, "named_move": "Closed Guard to Side Scissor (Elbow Across Centerline)", "ruleset": "gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-scissor*", "technique_steps": "1. From neutral closed guard, grip opponent's wrist with four fingers on top of the wrist, outside the cuff.\n2. Pull the hand and elbow toward your shoulder to bring the opponent's arm across the centerline.\n3. Once the hand and elbow pass the centerline, switch your grip so your hand is underneath the wrist, still with four fingers outside the cuff.\n4. Pull with your legs while pushing with your arm toward the opponent's opposite hip, creating a forward-roll off-balance and exposing the back.\n5. Shift hips and lock the feet to achieve the side scissor position.", "main_ideas": "Pull to the shoulder first, then switch to pushing toward the hip. Let the legs do the pulling once past centerline. Keep four fingers outside the cuff at all times.", "source_time_ranges": []}, {"id": "7f3ea568e29a", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Locking Down The Side Scissor", "chapter_start": 1826.0, "named_move": "Side Scissor Transition from Closed Guard", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "side-control", "technique_steps": "1. From closed guard, take the opponent's arm and bring it across the center line.\n2. Establish a push grip with the hand holding the arm, keeping it locked in place.\n3. Move out to the side into side scissor position.\n4. Lock down the arm using the lapel grip with a low elbow pulled to your hip.", "main_ideas": "Bring the arm across the center line. Lock it with a lapel grip. Keep the elbow low and pulled to your own hip.", "source_time_ranges": []}, {"id": "064e3e9a46bf", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Unlocking The Great Secret of the Side Scissor Position", "chapter_start": 2110.0, "named_move": "Side Scissor Back Take", "ruleset": "gi", "move_type": "back-take", "start_occupancy": "top", "start_position": "side-control", "end_occupancy": "top", "end_position": "back-control", "technique_steps": "1. From closed guard, break grips and get the opponent's arm across your centre line into side scissor.\n2. Secure the far side of the body and shift hips out, locking the side scissor.\n3. Reach through and grip the opponent's far lapel to keep their head down.\n4. Build up to an elbow with the elbow at shoulder line, getting your head higher than theirs.\n5. Put weight onto the top leg to unweight the bottom leg, make a strong body, and withdraw the bottom leg.\n6. Hook the far leg in, score the back, and secure back control.", "main_ideas": "Get your head higher than theirs. Build up to an elbow at shoulder line. Anchor their head down with the far lapel.", "source_time_ranges": []}, {"id": "f41295559120", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "The Wrist Sweep From Side Scissor", "chapter_start": 2514.0, "named_move": "Wrist Sweep From Side Scissor", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "side-scissor*", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, get the opponent's arm across your body and beat the arm so you are outside it.\n2. Access the opponent's far-side lapel and build up to an elbow, bringing your head higher than theirs.\n3. Keep your foot hooked across the opponent's stomach and move from elbow to hand so your head is directly behind them.\n4. Seize the opponent's wrist on the outside with a simple post grip, pressing it into the mat rather than lifting it.\n5. Step your knee past the opponent's shoulder, turn your head toward their hips, and use your opening knee as a lever on their hip to turn them over into mount.", "main_ideas": "Win the head position battle first. Post on the wrist and press it into the mat. Use the knee as a lever to turn them into mount.", "source_time_ranges": []}, {"id": "80cdd0971102", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "The Elbow Sweep From Side Scissor", "chapter_start": 3066.0, "named_move": "Elbow Sweep From Side Scissor", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "side-scissor*", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with the opponent on two knees, grip up, pull the knee to bring them in, and come out to the side. 2. Lock the side scissor and build up to an elbow by moving the head away from the opponent's head. 3. Once the head is higher, put all weight on the top leg and hook the bottom foot across. 4. If the opponent pushes and a hand is unavailable, drop to the elbow, pull it inward, and bring the knee over the shoulder. 5. Rotate through to finish in high mount.", "main_ideas": "Win head height first. Drop to the elbow when the hand is blocked. Cover the shoulder and rotate through into high mount.", "source_time_ranges": []}, {"id": "6af8a3a6492f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Rolling Armbar (Juji Gatame)", "chapter_start": 3377.0, "named_move": "Rolling Armbar (Juji Gatame)", "ruleset": "both", "move_type": "submission", "start_occupancy": "top", "start_position": "side-control", "end_occupancy": "", "end_position": "armbar", "technique_steps": "1. From closed guard with opponent on two knees, draw his arm across the center line.\n2. Hook the foot across his body, contoured like a hand gripping his hip, and get head higher than his.\n3. Put your head on the floor, come around to his shoulder line, and secure the near arm elbow to elbow.\n4. Take the leg over the top, hook his head, and bring the knee inside his elbows pointing toward his crotch.\n5. Drop to a shoulder to load weight onto him, then reach across for the far leg (or grab the near leg if the far is out of reach) and draw it inward.\n6. Pull everything across your chest so he turns through, adjust, and finish with juji gatame.", "main_ideas": "Draw the arm across the center line first. Hook your foot like a hand on his hip. Pull the legs to your chest, not up to the ceiling.", "source_time_ranges": []}, {"id": "852d58889c25", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Side Scissor into Rear Triangle (Ushiro Sankaku)", "chapter_start": 3779.0, "named_move": "Side Scissor into Rear Triangle (Ushiro Sankaku)", "ruleset": "gi*", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "", "end_position": "triangle", "technique_steps": "1. From closed guard, get a working grip on the opponent's arm (e.g. two-on-one cuff) and turn their arm across the center line.\n2. Come out to the side and lock up the side scissor, beating the opponent's elbow.\n3. If the opponent keeps the elbow down, scoop the near arm, bring the knee over the opponent's head and hook inside the bicep.\n4. Turn the knee through underneath the opponent and press on the back of their neck, connecting their knuckles to your chest.\n5. Stand on the opponent's hip, shift hips to the side, and lock up the rear triangle, getting shoelaces behind the lap muscle.\n6. Squeeze with the legs for the strangle.", "main_ideas": "Beat the elbow and get your head above theirs.\nConnect their knuckles to your chest.\nSqueeze with your legs.", "source_time_ranges": []}, {"id": "36d1621f4f95", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Side Scissor into Rear Triangle (Ushiro Sankaku)", "chapter_start": 3779.0, "named_move": "Side Scissor Rolling Armbar (Juji Gatame)", "ruleset": "both*", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "", "end_position": "armbar", "technique_steps": "1. From closed guard, turn the opponent's arm across the center line and lock up the side scissor.\n2. Foot pushes inward, the other leg pulls, and the knee is brought straight across to the chest to draw the partner over.\n3. Finish the arm lock.", "main_ideas": "Pull them over with your leg.\nFinish the arm lock.", "source_time_ranges": []}, {"id": "9d7660b82f4e", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Side Scissor Position Working with Lower Head Position: Flower Sweep", "chapter_start": 4121.0, "named_move": "Flower Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with the opponent's arm trapped across the center line and his head higher, plant your foot right next to his knee (the one on the side you're sweeping toward) and do not shift your hips out.\n2. Extend the leg outward with toes pointing outward and bring the straightened leg up toward his armpit without hitting into his body.\n3. Touch your foot toward the floor on that side, sweeping over the shoulder rather than directly to the side, so his leg cannot be used as a base.\n4. Push off your bottom leg to crawl up his body and arrive in high mount with knees hooked down and feet close together, keeping his arms trapped for armbar attacks.", "main_ideas": "Trap the arm across the center line first.\nPlant your foot outside his knee so he has no base.\nSweep over the shoulder, keep your hips aligned, and crawl up into high mount.", "source_time_ranges": []}, {"id": "ffe8372d0725", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Side Scissor Position Working with Lower Head Position: Flower Sweep", "chapter_start": 4121.0, "named_move": "Flower Sweep (Lap Muscle Variation)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with the opponent's arm trapped across the chest and his head coming over yours, capture his lap muscle (hip area) as the head passes.\n2. Plant your foot at the knee so he cannot put a foot out for base.\n3. Without shifting your hips, bring the straightened leg up and over and hook into his hips.\n4. Finish in a mounted position with his arms still trapped, ready to attack from top.", "main_ideas": "Capture the lap muscle while his head comes over.\nPlant at the knee to stop his base.\nHook the hips and finish in mount.", "source_time_ranges": []}, {"id": "d8d783052b86", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Pendulum Sweep", "chapter_start": 4453.0, "named_move": "Pendulum Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "side-scissors-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, get an effective working grip that brings the opponent's arm across your centerline (win elbow position).\n2. If the opponent wins head position, release his lapel and hunt for his leg, getting elbow deep inside the leg with a scoop grip.\n3. Pull up so his knee and head come relatively close together.\n4. Use your bottom leg to turn your hips to point forward, the direction he cannot base out in because his arm is trapped.\n5. Swing your leg low around the floor, knee first then foot, moving his body weight forward and creating kuzushi.\n6. Drive your top leg through in an axe-kick action to take him over, keeping your head low toward his belt.\n7. Move your bottom leg away toward his hips so he lands beside it rather than on it.\n8. Hook into your partner and arrive in mount.", "main_ideas": "Keep the trapped arm forward. Bring his head to the mat. Never throw him onto your own leg.", "source_time_ranges": []}, {"id": "72d28d966d9f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Knee Lever sweep", "chapter_start": 4924.0, "named_move": "Knee Lever Sweep", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "half-guard", "technique_steps": "1. From closed guard, get a solid working grip on the training partner's arm and draw the elbow across the centerline. 2. If the opponent recovers head position and drives knees up off the floor putting weight on you, shuffle hips and pommel the leg through, elevating out to the side into half guard. 3. Chop the inside leg over the opponent's knee and staple it down to the mat. 4. Cross the toes (not the ankles), bring hips slightly off the floor, and point knees in the direction of the sweep. 5. With the trapped leg down and opponent lacking base, come up on top into a passing position.", "main_ideas": "Win elbow position first. Staple the opponent's knee to the mat with the inside leg. Cross your toes, lift your hips, and tilt your knees over.", "source_time_ranges": []}, {"id": "623c7add52a1", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Hook Sweep (Sumi Gaeshi)", "chapter_start": 5220.0, "named_move": "Hook Sweep (Sumi Gaeshi)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "closed-guard", "technique_steps": "1. Start in closed guard, bottom. 2. Send the training partner's arm past you and capture it. 3. Turn the hips to create an angle and get a strong hook in. 4. Lift and move the partner, then pommel the second foot in so both feet are under the partner's thighs. 5. Bring the knees to the chest so the partner's hips rise above their head. 6. Rotate the partner's body to create sweep directionality. 7. Push with the right hand to finish on top in a perfect passing position.", "main_ideas": "Turn the hips to hook when head position is lost. Get both feet under the thighs. Lift the hips above the head, then rotate and push.", "source_time_ranges": []}, {"id": "c488cc055e2a", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Hook Sweep (Sumi Gaeshi) Part 2", "chapter_start": 5466.0, "named_move": "Hook Sweep Part 2 (Side Scissor Sweep)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "side-control", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. Start in neutral closed guard with the opponent's arm trapped across and the opponent holding head position in a side scissor type situation. 2. Opponent tripods and pushes into you; shift hips out to the side and start a hook inside the opponent's legs. 3. Lift with the right leg to get the opponent hopping in the opposite direction of the trapped arm, extending their base. 4. Place the left foot on the opponent's shin and cut it away to the west as the right leg lifts east. 5. Finish with the opponent swept from chest-down to chest-up, ending in top position.", "main_ideas": "Lift with one leg to make the opponent hop. Cut the remaining base with the other leg in the opposite direction. Sweep with double directionality.", "source_time_ranges": []}, {"id": "78b9b36aa664", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Troubleshooting The Transition From Closed Guard To Side Scissor: Shoulder Posting", "chapter_start": 5739.0, "named_move": "Shoulder post to hand from closed guard side scissor transition", "ruleset": "gi", "move_type": "transition", "start_occupancy": "neutral", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "back-control", "technique_steps": "1. From closed guard, establish a working grip on the opponent's jacket and send their arm across the body to win elbow position.\n2. Move to the side to win head position, getting your head higher than theirs.\n3. If the opponent drives forward and prevents an elbow prop, place a foot on their hip and push back.\n4. Get a grip on the opponent's far lapel.\n5. Lift the hips and come up onto the shoulder, using the head as base of support.\n6. Push off the mat with the lower leg and turn the chest toward the floor so the arm is unweighted.\n7. Build up to a hand and get hooks in on the opponent.\n8. Turn the opponent over and take the back.", "main_ideas": "Drop to the shoulder when the elbow prop is blocked. Push back with feet first to create room. Post to a hand once the arm is unweighted.", "source_time_ranges": []}, {"id": "b601c60a5ff8", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Troubleshooting The Transition From Closed Guard To Side Scissor: Shoulder Posting 2", "chapter_start": 6262.0, "named_move": "Shoulder-posted pendulum sweep from closed guard side scissor", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control*", "technique_steps": "1. From closed guard, take the training partner's arm straight by and get your head from underneath the opponent. 2. Secure the far lapel. 3. Push back with the legs, straighten the body, and turn the chest down toward the floor. 4. If forward pressure prevents an elbow prop, prop up on the shoulder instead. 5. Place the foot on the hip or just above the knee and push the knee to break the base. 6. Scoop inside the opponent's leg to trap the arm and create a superior sweeping angle. 7. Pendulum sweep the opponent over, finishing in good position on top.", "main_ideas": "Prop off the shoulder when forward pressure blocks the elbow. Break the base with the foot on the knee. Scoop inside the leg and sweep with the pendulum.", "source_time_ranges": []}, {"id": "f68b80aac172", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Troubleshooting The Transition From Closed Guard To Side Scissor: Shoulder Posting 3- Overcoming Biggest Problem with Side Scissor: Hip Sweep", "chapter_start": 6440.0, "named_move": "Elbow-Up Hip Sweep from Closed Guard (Side Scissor Counter to Elbow Pullback)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with the opponent on two knees, cuff the opponent's sleeve and attempt to draw the elbow across the centerline. 2. When the opponent pulls the elbow back and away, open the guard and go in the same direction he is pulling, keeping feet in the same position. 3. Take the elbow back behind you and plant the left foot on the mat. 4. Take the training partner's wrist forward and point your chest at the floor. 5. From the elbow position, drive the knee forward across the body while the left leg steps around the corner. 6. Finish in mount on top of the training partner.", "main_ideas": "Go with the pull, not against it. Come up to an elbow and drive across. Step around and finish in mount.", "source_time_ranges": []}, {"id": "1104e4192b69", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Troubleshooting The Transition From Closed Guard To Side Scissor: Shoulder Posting 3- Overcoming Biggest Problem with Side Scissor: Hip Sweep", "chapter_start": 6440.0, "named_move": "Scissoring Elbow Sweep to Mount", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, establish a cuff grip and attempt to draw the elbow across. 2. If resisted, come straight up from the supine position to an elbow as the guard opens. 3. Plant one foot, pull the opponent forward to create kazushi with the hand. 4. Drive the hips forward and step right across the training partner's body, with one leg cutting back while the other pushes across, creating a scissoring turnover. 5. Finish in strong mount on top.", "main_ideas": "Come straight up to an elbow. Use double-directional scissoring. Step across to mount.", "source_time_ranges": []}, {"id": "8bcc9227673d", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Overview of the Side Scissor Series", "chapter_start": 6831.0, "named_move": "Side Scissor Entry via Elbow Across Center Line", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "side-control*", "technique_steps": "1. From closed guard with opponent on two knees, secure a strong cross-cuff grip, usually attacking the rear hand. 2. Break the opponent's grip on the cloth. 3. Establish a two-on-one grip. 4. Pull with the knees, then push with the hands so the arm traps across the body. 5. Open the body out and away to get outside the opponent's arm and reach behind them. 6. Assert dominance in the side scissor position with the elbow trapped across center line and the far lapel or lat gripped.", "main_ideas": "Pull with the knees, not just the hands. Attack the rear hand in most cases. Open out and away to beat a posting hand.", "source_time_ranges": []}, {"id": "dbc52a49624e", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E03 - Side-Scissor.mp4", "chapter_title": "Overview of the Side Scissor Series", "chapter_start": 6831.0, "named_move": "Hip Sweep Fallback from Closed Guard", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control*", "technique_steps": "1. If the elbow cannot be brought across the center line, come up to an elbow. 2. Use the elbow to sweep the opponent over. 3. Take top position.", "main_ideas": "Come up to an elbow and sweep when the elbow will not cross. Take top position through the sweep.", "source_time_ranges": []}, {"id": "621b5b12504b", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E04 - Arm Bar.mp4", "chapter_title": "The Top Lock/Armbar - The Top Lock", "chapter_start": 0, "named_move": "Top Lock", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "top-lock*", "technique_steps": "1. From closed guard (bottom), take a cuff grip on the opponent's arm and break their grip on the cloth using the heel of your hand over their knuckles. 2. Draw the opponent's elbow forward toward your sternum, bringing it toward (not necessarily across) the center line and inside your hip. 3. Take a reverse collar grip across. 4. Throw one calf over the opponent's trapezius and shoulder and lock the ankles. 5. Raise the hips into a straight line when the opponent tries to pull out, keeping control at the high end of the spine lever.", "main_ideas": "Bring the elbow inside the hip toward the center line. Throw the calf over the shoulder and lock the ankles. Raise the hips to stop the arm from pulling out.", "source_time_ranges": []}, {"id": "3ad9fc1fa627", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E04 - Arm Bar.mp4", "chapter_title": "The Number One Grip", "chapter_start": 532.0, "named_move": "Top lock entry from closed guard via overclasp and cross grips", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "top-lock*", "technique_steps": "1. From closed guard, opponent grips up with a lapel/collar grip and has elbows flared or stiff-arming. 2. Open up the opponent's lapel and draw him inward, gripping high with the thumb behind his ear. 3. If an underclasp is blocked, go over his arm with an overclasp and get the elbow on top of his elbow to break posture downward. 4. Bring a cross cuff grip on his wrist and feed his hand toward the centerline. 5. Take the second hand into a cross collar grip, reaching all the way behind his neck. 6. Pull inward with both legs to break his upper body forward to about 45 degrees and drive his elbow inward. 7. Shimmy the legs up his back and lock the feet over his shoulder into the top lock.", "main_ideas": "Get the elbow inside the hip. Break posture with the overclasp. Pull inward with the legs and grips together.", "source_time_ranges": []}, {"id": "41dab495a71c", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E04 - Arm Bar.mp4", "chapter_title": "Attacking With the Arm Lock (Juji Gatame) From Top Lock Position", "chapter_start": 1227.0, "named_move": "Juji gatame from top lock", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "top-lock*", "end_occupancy": "", "end_position": "armbar*", "technique_steps": "1. From closed guard bottom, break opponent's posture with cross cuff grip and overclasp leading to cross collar behind the neck.\n2. Turn body onto its side and pull in with arms, shimmy hips, lock the top lock.\n3. Bring the cuff-grip hand to the center line and go wrist to wrist, putting your wrist on top of his to prevent a figure four with his arms.\n4. Touch your foot to the back of his head and pass the leg over the top, shifting from one shoulder to the other.\n5. Bring both feet down low with knees higher than feet and hips high, then apply breaking pressure to the arm.", "main_ideas": "Control the shoulders with the top lock first. Take wrist control to stop the figure four. Keep feet low with heels pointing down and hips high.", "source_time_ranges": []}, {"id": "62cba80f518f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E04 - Arm Bar.mp4", "chapter_title": "Arm Bar (Juji Gatame) From Closed Guard", "chapter_start": 2641.0, "named_move": "Armbar from Closed Guard (Juji Gatame) via top lock", "ruleset": "gi", "move_type": "submission", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "", "end_position": "armbar", "technique_steps": "1. From closed guard, establish 45 inside: tie up the arm with cross-cuff and cross-lapel grips so the opponent's pull is blocked. 2. Walk the climbing leg up the lat and middle back, bringing the knee onto the opponent's shoulder while keeping hips high to form the top lock. 3. Remove the cross-lapel hand from the lapel and post it on the opponent's shoulder; bring your wrist veins onto his wrist veins. 4. Touch the foot to the back of his neck. 5. Pivot off the shoulder with a windshield-wiper motion from in front of him to the side so both feet face the same direction. 6. Bring the leg over the top with the knee higher than his ear and the feet close together, driving the hips into the armbar finish.", "main_ideas": "Get the 45 inside and walk up to a high top lock. Keep hips high and your feet close. Pivot shoulder to shoulder with a small movement.", "source_time_ranges": []}, {"id": "0994314120d5", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Knees/Hip On Floor - Flower Sweep", "chapter_start": 0, "named_move": "Flower Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with opponent on two knees, secure a cuff grip on his sleeve with four fingers on the outside seam, wrist over his wrist.\n2. Secure a pant cuff grip on his trouser leg with four fingers on the outside seam; do not insert fingers.\n3. Plant the foot tight to the outside of his ankle, turning the foot out rather than shifting the hips, to trap the leg and prevent posting.\n4. Use the hamstring and a straight leg to bump his head forward while pulling his fist back, breaking his balance forward.\n5. Once his head passes over his fist, push with the legs and lift with the arms, keeping control of his leg.\n6. Stabilise, come up on top, and climb to a dominant position, finishing with the arm pulled into mount.", "main_ideas": "Trap the ankle, don't pivot the hips. Let the straight leg bump him forward. Finish up high with hips over his.", "source_time_ranges": []}, {"id": "45c0edf45ea3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Knees/Hip On Floor - Flower Sweep", "chapter_start": 0, "named_move": "Hip Sweep (preview)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "", "technique_steps": "", "main_ideas": "", "source_time_ranges": []}, {"id": "b5a6384fd1ed", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "The Hip Sweep", "chapter_start": 666.0, "named_move": "Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, the opponent is on two knees in front of you; sit up on top of the opponent's hips. 2. Control the opponent's near arm/knee, collecting the hand that would serve as their base. 3. Get up to a hand (preferred) or elbow, chest facing down. 4. Drive the knee down toward the mat and bring the hips forward, loading the opponent's weight onto their knee. 5. Step across and throw the opponent forward, finishing with the opponent landing on the line from your base of support.", "main_ideas": "Keep your chest facing down. Throw forward, never backward. Collect the hand first.", "source_time_ranges": []}, {"id": "c7a439085cd0", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Hip Sweep Setup - Misdirection", "chapter_start": 1401.0, "named_move": "Misdirection sit-up to hip sweep setup", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard with opponent on top and hands on your chest or biceps, open the guard and place all weight on the points of your shoulders. 2. Shoot both arms overhead. 3. Misdirect your head and upper body to one side, drawing the opponent's head and hands that way. 4. Whip back the opposite direction and sit up to that side. 5. Place the hand behind you, not out to the side, and come up on your hips. 6. Turn your chest down to the mat so the opponent's weight loads onto his knee. 7. Touch a knee to the mat and step a big step over the top to mount.", "main_ideas": "Misdirect one way, sit up the other. Hand behind you, hips high. Keep your chest facing the mat.", "source_time_ranges": []}, {"id": "afaaefb81ec4", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Hip Sweep Setup - Misdirection", "chapter_start": 1401.0, "named_move": "Misdirection sit-up with scoop of the arm", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with opponent on top, open the guard and place weight on the shoulder points. 2. Shoot arms overhead and misdirect to one side. 3. Sit up to the other side. 4. Scoop up the opponent's arm on that side. 5. Keep the chest facing down with hips high. 6. Step a big step over the top into mount.", "main_ideas": "Misdirect one way, sit up the other. Scoop the arm and keep your chest down.", "source_time_ranges": []}, {"id": "33a3801502a6", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Hip Sweep Setup - Cross Elbow Post", "chapter_start": 1681.0, "named_move": "Cross Elbow Post to Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with opponent's hands on upper body and no gi grip, slide the hand underneath the opponent's arm. 2. Cross post at the elbow with thumb just inside the elbow. 3. Turn onto your side and push everything out, coming up as the opponent takes his arm back. 4. Come up to an elbow or hand, turning chest down to the floor with hips high. 5. Collect the opponent's elbow and hip sweep into mount.", "main_ideas": "Post at the elbow and turn out to the side. Keep chest down and hips high. Sweep once you are up.", "source_time_ranges": []}, {"id": "3114103082d9", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Hip Sweep Setup - Cross Elbow Post", "chapter_start": 1681.0, "named_move": "Cross-Cuff Grip Break to Side Scissor Sit-Up", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. Against an opponent gripping your feet or lapels, take a cross-cuff grip and grab your own wrist. 2. Use knees in a knee pull to break the opponent forward. 3. Combine with an overhead movement that takes his hand across the centerline. 4. When he posture up and pulls his elbow back, let him go and sit up with feet on the floor. 5. Turn chest down, collect the elbow, drive a knee to the mat, step forward and throw him down.", "main_ideas": "Break the grip without pulling back toward yourself. Threaten the side scissor to force posturing up. Sit up into the sweeping position when he reacts.", "source_time_ranges": []}, {"id": "c44c47871e43", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Breaking Your Opponent’s Posture - Flower Sweep to Hip Sweep", "chapter_start": 2396.0, "named_move": "Flower Sweep to Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard with the opponent on two knees, grip the opponent's sleeve or collar.\n2. Plant the foot tightly on the opponent's ankle to trap it.\n3. Place the other hand inside the opponent's knee for a fast grip.\n4. Bump the opponent with the leg to break posture so an elbow or hand drops toward the floor.\n5. As the opponent recovers, bring the body up and outside the arms, elevate the hips, and turn the chest toward the opponent.\n6. Send the opponent over with the classic hip sweep to finish mounted.", "main_ideas": "Break posture before sweeping. Put hands and chest down to the mat. Finish with the hip sweep.", "source_time_ranges": []}, {"id": "8922f60b0a16", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Breaking Your Opponent’s Posture - Collar Tie Method", "chapter_start": 2783.0, "named_move": "Collar Tie Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, get inside position with one hand and post on the training partner's shoulder to come up. 2. Take a loose collar tie on the partner. 3. Drive hips up and bump so the partner bases out on the floor. 4. Cross over the partner's body and go chest down to the mat, keeping pressure that forces his posted hand to the mat. 5. Take his base hand and go wrist deep around his elbow. 6. Bring his hand toward your hand, then hip sweep to take top position.", "main_ideas": "Force the hand to the mat with a collar tie. Get chest down before sweeping. Collect the posted hand and sweep.", "source_time_ranges": []}, {"id": "19b7afa59728", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Breaking Your Opponent’s Posture - Collar Tie Method", "chapter_start": 2783.0, "named_move": "Headlock Hip Sweep", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, get inside position and post on the partner's shoulder to come up. 2. Get around the partner's head with a collar tie or headlock grip. 3. Bring a foot up and bump the opponent to force his hand to the mat. 4. Collect the posted hand while it is on the floor. 5. Hip sweep to take top position.", "main_ideas": "Bump to force the hand to the mat. Collect the hand on the floor. Sweep to top.", "source_time_ranges": []}, {"id": "7a23ccc670f3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Breaking Your Opponent’s Posture - Collar Tie Method", "chapter_start": 2783.0, "named_move": "Elbow Collar Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, bring hands inside the partner's and post on his body to come up to an elbow. 2. Pass the hand through, catch, and come up. 3. Give a healthy bump that forces his hand to the mat. 4. Collect the arm at the elbow and bring his hand around the corner. 5. Hip sweep to take top position.", "main_ideas": "Post to come up to elbow. Bump to force the hand down. Collect the elbow and sweep.", "source_time_ranges": []}, {"id": "a4a815040081", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Breaking Your Opponent’s Posture - Scoop Sweep to Hip Sweep", "chapter_start": 2988.0, "named_move": "Scoop Sweep to Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard with the opponent standing in front, get elbow deep inside the opponent's ankle.\n2. Lift the pelvis and place a hand on the mat or grab the sleeve cuff.\n3. Bring hips up and turn them outward, breaking the opponent down to a hip.\n4. Get head outside and knee to the mat, chest down over the opponent with hips on top of his.\n5. As the opponent tries to recover, take his hand off the mat.\n6. Complete the hip sweep, placing the opponent on his back and finishing in mount.", "main_ideas": "Break the posture down to the hip first. Get chest down with hips on top. Take the hand off the mat and sweep.", "source_time_ranges": []}, {"id": "1296e822a3c3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Breaking Your Opponent’s Posture When Your Opponent Posts One Leg: Scoop Sweep to Hip Sweep", "chapter_start": 3345.0, "named_move": "Scoop Sweep to Hip Sweep (single posted leg)", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, the opponent posts one leg up without fully standing. 2. Scoop inside the posted leg's ankle with your elbow and pull it forward. 3. Drive your hips down and sit into a hip to set the opponent down on his backside. 4. Bring your hands down toward the floor while bringing everything over the top. 5. Bring your knee to the mat and chest down as the opponent tries to recover. 6. Step the opponent over and put him down to complete the hip sweep reversal.", "main_ideas": "Scoop the ankle and drive your hips to set the opponent down. Keep the hip on the floor. Bring the chest down and step over.", "source_time_ranges": []}, {"id": "0e355826afea", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "Cross Cuff Hip Sweep", "chapter_start": 3561.0, "named_move": "Cross-Cuff Hip Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard with the opponent on two knees gripping your jacket, grip the opponent's sleeve cuff, placing your hand over theirs.\n2. Take the opponent's grips off by placing a hand on your own collar and breaking their grip.\n3. Control the opponent's hand so their left hand cannot stop you rising.\n4. Separate the feet and shift the hips slightly to open the guard.\n5. Pull the elbow behind you to control the sleeve cuff, keeping the elbow close rather than out to the side.\n6. When the opponent drives you down, bring the hips up off the floor and turn the chest down toward the mat.\n7. Bring the opponent's hand around the corner, step over, and finish in mount.", "main_ideas": "Grip the sleeve cuff first and break their grips.\nPull your elbow behind you and bring your hips up.\nTurn your chest down and drive them forward into the sweep.", "source_time_ranges": []}, {"id": "c893c9b73e59", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "The Hip Sweep: Putting It All Together", "chapter_start": 4098.0, "named_move": "Sleeve-grip hip bump sweep from knees", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "half-guard*", "end_occupancy": "top", "end_position": "side-control*", "technique_steps": "1. Start on knees with a sleeve grip on the training partner. 2. Get one hand inside the sleeve. 3. Bounce the opponent down to the side as he recovers, breaking him to a hip. 4. Drop chest to the floor. 5. Finish by sweeping the opponent to the mat and reaching mount.", "main_ideas": "Grab the sleeve and put a hand inside. Bounce him to the side. Drop your chest and sweep.", "source_time_ranges": []}, {"id": "98f46261c0dc", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "The Hip Sweep: Putting It All Together", "chapter_start": 4098.0, "named_move": "Two-stage hip bump sweep from headlock or collar tie", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "front-headlock*", "end_occupancy": "top", "end_position": "side-control*", "technique_steps": "1. Start in a headlock or collar tie. 2. Hit an initial hip bump. 3. Bump the opponent's hand down so it touches the mat. 4. Once the hand touches the mat, bring in the second step to return him to the mat. 5. Finish on top in mount.", "main_ideas": "Bump the hip to bring his hand down. Once the hand touches the mat, come through.", "source_time_ranges": []}, {"id": "33c5396195f8", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E05 - Hip Sweep.mp4", "chapter_title": "The Hip Sweep: Putting It All Together", "chapter_start": 4098.0, "named_move": "Cross-cuff hip sweep from elbows", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "collar-sleeve*", "end_occupancy": "top", "end_position": "mount*", "technique_steps": "1. Hold the training partner's cross-cuff grip. 2. Work from the elbows. 3. Draw everything forward and drop chest to the mat. 4. Score a knockdown. 5. Finish mounted.", "main_ideas": "Hold the cross-cuff. Draw forward and drop your chest.", "source_time_ranges": []}, {"id": "78607e263cf3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "Scissor Sweep", "chapter_start": 0, "named_move": "Scissor Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, take a cross lapel grip with one hand and a sleeve cuff grip with the other, covering the opponent's wrist with your wrist. 2. Shift hips out to the side and bring the top knee through, anchoring it on top of your own wrist so the opponent's gi holds the knee in place. 3. Drop the second foot to the opponent's hip and begin to straighten the body. 4. Hook the shoelaces into the opponent's lat muscle and draw him forward with the leg and hands so his head moves in front of his knees. 5. Load all of his weight onto one knee with the top scissor leg. 6. Scissor the bottom leg through to remove that base and drop him toward the shoulder line, then get up on top.", "main_ideas": "Keep knees apart and anchored. Draw the head forward past the knees. Load one knee, then sweep it away toward the shoulder line.", "source_time_ranges": []}, {"id": "2a3f6a222018", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "Scissor Sweep", "chapter_start": 0, "named_move": "Scissor Sweep with Push on Knee", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, when the opponent's knee sits far outside his hip, place a foot on his knee rather than hooking. 2. Push the knee down the mat. 3. Apply the same scissoring force as the standard scissor sweep to drop him, producing a low-amplitude sweep to the floor.", "main_ideas": "Push the far-out knee down the mat. Scissor him down with a low-amplitude sweep.", "source_time_ranges": []}, {"id": "45f7bdc8ece0", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "Scissor Sweep", "chapter_start": 0, "named_move": "Scissor Sweep with Reaping Calf", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, when the opponent's hip is directly over his knee, put the hip over the knee. 2. Use the foot and calf muscle from the outside of the leg to reap inward. 3. The reaping motion puts the opponent down with a higher-amplitude sweep to the mat.", "main_ideas": "With the hip over the knee, reap inward with the calf. Get a high-amplitude sweep.", "source_time_ranges": []}, {"id": "8845ec31e737", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "Scissor Sweep Double Sleeve Grips", "chapter_start": 881.0, "named_move": "Scissor Sweep (Double Sleeve Grip)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "closed-guard", "technique_steps": "1. From closed guard, secure a cuff grip on one of the opponent's sleeves, then take the second hand high on the tricep near the armpit and shoulder, gripping the seam on the back of the sleeve.\n2. Scissor the legs out, bringing the body out to the side and placing the knee just inside/in front of the opponent's shoulder or armpit, with the shin against the opponent's back.\n3. Use the foot and the opponent's back to draw their head forward and load all of their weight onto one knee.\n4. Attack the loaded knee: reap with the outside calf if the knee is over the hip, or push the knee out if the knees are far apart.\n5. Scissor the opponent over and come up on top.", "main_ideas": "Load all the weight onto one knee. Reap or push that knee depending on knee position. Use the sleeve grip to start the scissor quickly.", "source_time_ranges": []}, {"id": "1f068baba1a9", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "2 On 1 Grip Scissor Sweep", "chapter_start": 1196.0, "named_move": "2-on-1 Grip Scissor Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "standing", "technique_steps": "1. From closed guard, secure a cross-cuff grip: your left hand on his left sleeve cuff, and your other hand on the back of his tricep at the seam running down the sleeve. 2. Lock the tricep grip high on the arm. 3. Pivot your hips out and bring one knee forward in front of his shoulder, with the second foot to his hip. 4. Bring his head forward and load his weight onto one leg by pulling him forward with the knee. 5. Drop the foot to reap (if the hip is over the knee) or push (if his knees are far apart), driving his weight over the knee with a high scissor action and a foot in his lower back to draw his head forward. 6. Send him over with the scissor sweep to finish on top.", "main_ideas": "Lock the cross-cuff and the tricep seam before you move. Load his weight onto one knee first. Finish with a reap or push depending on knee spacing.", "source_time_ranges": []}, {"id": "7333c5abf16c", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "Scissor Sweep On a Posted Leg", "chapter_start": 1380.0, "named_move": "Scissor Sweep on a Posted Leg", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "standing", "technique_steps": "1. From closed guard, identify the opponent's knee that remains on the mat as they post one leg to stand.\n2. Turn the body toward the knee on the mat, bringing the knee up onto your own wrist.\n3. Place the foot on the opponent's hip to stabilize distance.\n4. Apply the top half of the scissor first to off-balance the opponent.\n5. Drop the lower leg and draw the opponent's weight forward, putting their head over their knee.\n6. Complete the full scissor by moving the foot off the hip, taking the opponent over and sweeping them to the mat.", "main_ideas": "Sweep toward the knee on the mat, never toward the posted leg. Time the attack to the first leg coming up. Stabilize with the foot on the hip before the scissor.", "source_time_ranges": []}, {"id": "67934578e3b3", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Pendulum Sweep", "chapter_start": 1597.0, "named_move": "Pendulum Sweep", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, grip the opponent's tricep at the seam on the back of the sleeve with one hand. 2. Bring his other hand toward the center line and pull his hips forward to open space between his butt and ankle. 3. Open the guard behind his back and get an elbow deep inside his legs. 4. Split the legs and invert the sweeping knee so knee and toes point down to the mat. 5. Pull his head forward over your head and bring your hand to your own head so his body floats over you. 6. Brush the leg down toward the floor and throw the sweeping leg like an axe kick, keeping the second leg scissoring so no part of his body lands on your bottom leg. 7. Put hands and head on the mat, come up onto the top, and walk into mount.", "main_ideas": "Pull his weight forward and go deep inside the leg. Split the legs with the knee and toes pointing down. Keep his weight off your bottom leg and finish on top.", "source_time_ranges": []}, {"id": "e8cde67af00d", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Pendulum Sweep", "chapter_start": 1597.0, "named_move": "Pendulum Sweep (Arm Trapped Across Center Line)", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, trap the opponent's arm across the center line. 2. Pull his head forward using the closed guard and pull in with the legs so he cannot break the grip. 3. Take the scoop grip. 4. Throw the sweeping leg like an axe kick while the second leg crosses the mat at about 90 degrees, so he lands over, not on, your bottom leg. 5. Connect to his hips through your feet and secure the mount.", "main_ideas": "Trap the arm across the center line. Pull in with the legs and bring his head forward. Keep his weight off your bottom leg.", "source_time_ranges": []}, {"id": "b84f7f8342b2", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "Pendulum Sweep With Cuff Grip", "chapter_start": 2611.0, "named_move": "Pendulum Sweep With Cuff Grip", "ruleset": "gi*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, establish a cuff grip on the opponent's wrist with your wrist on top of his.\n2. Pull inward with both legs to expose the inside of the leg and get your grip on the opponent's pants or leg.\n3. As the opponent posts up, whip your body through and get your lead foot's toes to the mat, creating an asymmetrical split with one knee pointing down.\n4. Bring the leg around the corner and use an axe-kick motion to drive the opponent over.\n5. Drive up into your two hands, lock your feet around his head, and finish in mount.", "main_ideas": "Cover the wrist, not the shoulder. Pull in before you sweep. Let the lead foot touch first, then axe kick, then the second foot.", "source_time_ranges": []}, {"id": "f4617d4c05d9", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Strongest Pendulum Sweep: Trapping The Arm", "chapter_start": 3137.0, "named_move": "Pendulum Sweep (Arm Trap)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "technical-mount", "technique_steps": "1. From closed guard, grip the training partner's sleeve cuff and bring your hand through to grab your own wrist. 2. Pull in with both legs and look up at the ceiling so his hand goes over your head. 3. In one motion, bring his trapped arm across the centerline. 4. Open the closed guard behind his back, shift hips out to the side, invert the right knee, and grip at the lat muscle to reach side scissor. 5. Pull in with both legs to create space, scoop elbow-deep inside his leg, and grip over-back. 6. Loosen the leg and extend so his head and body weight come forward, touching the foot to the mat. 7. Perform the axe kick motion, putting the right foot down on the mat. 8. Come up into mount with his arm trapped across the body.", "main_ideas": "Trap the arm across the centerline before starting the sweep.\nScoop deep inside the leg and grip over-back to keep him close.\nFinish by coming up into mount with his arm still trapped.", "source_time_ranges": []}, {"id": "b33c60274bb4", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Versatility of The Arm Trap", "chapter_start": 3549.0, "named_move": "Pendulum Sweep from Double Sleeve Arm Trap", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control*", "technique_steps": "1. From closed guard, establish a double sleeve grip on the opponent's trapped arm: four fingers over the forearm, grabbing a flap of cloth. 2. Raise the hips, then drop and push with the hands. 3. Pull inward with the legs to bring the opponent's elbow toward the centerline; if the elbow won't move, shift your body around it. 4. Shift the hips out until the arm is trapped. 5. Get inside the opponent's legs and use the left leg to start momentum, bringing the opponent forward into a pendulum sweep to the mat.", "main_ideas": "Grab a flap of cloth with four fingers and pull with your legs. Move yourself around the elbow if it won't move. Use the left leg to start the pendulum sweep.", "source_time_ranges": []}, {"id": "928aba740e6c", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Versatility of The Arm Trap Part 2", "chapter_start": 3747.0, "named_move": "Arm trap pendulum sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "standing*", "technique_steps": "1. From closed guard, shift hips out until the elbow is beaten.\n2. Bring the training partner forward with the leg action.\n3. Left leg starts the momentum, producing a pendulum sweep down to the mat.", "main_ideas": "Shift hips out until the elbow is beaten.\nUse the left leg to start the pendulum.\nSweep the partner down to the mat.", "source_time_ranges": []}, {"id": "e83f3acb0b9c", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Versatility of The Arm Trap Part 2", "chapter_start": 3747.0, "named_move": "Cross cuff arm trap sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "standing*", "technique_steps": "1. Attack the rear hand when the lead arm is too strong.\n2. Take a cross cuff grip on the partner's rear sleeve cuff and brush the hand toward the centre line.\n3. Grab the seam on the partner's tricep with the second hand.\n4. Pull in with the legs, not the hands, while shuffling hips outside.\n5. Reach around the back and draw the elbow forward to establish the arm trap.\n6. Bring the hand under the partner's legs and use the leg action to draw them up and put them to the floor.", "main_ideas": "Attack the rear hand toward the centre line.\nPull with the legs, not the hands.\nShuffle outside and draw the elbow forward.", "source_time_ranges": []}, {"id": "1c9f6b629071", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Versatility of The Arm Trap Part 3", "chapter_start": 3963.0, "named_move": "Arm trap to pendulum sweep from turtle/rear mount recovery", "ruleset": "both", "move_type": "sweep", "start_occupancy": "top", "start_position": "turtle", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From a turtle-style top position with a hook in, lose the hook as the opponent shrugs and bumps you down while keeping their arm trapped.\n2. Grip the training partner's jacket as they square up on top of you.\n3. Hit a simple elbow escape to bring your leg out and walk up into a closed guard with the arm trap.\n4. Shift hips out into a side scissor position with the trap down.\n5. As the opponent pulls away, pull in, get a scoop grip under their leg, and execute the pendulum sweep to come up on top.", "main_ideas": "Keep the arm trapped even when position is lost. Recover into closed guard or side scissor. Sweep with the pendulum action.", "source_time_ranges": []}, {"id": "b653efd489c8", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Versatility of The Arm Trap Part 3", "chapter_start": 3963.0, "named_move": "Arm trap recovery from seated rear mount into side scissor sweep", "ruleset": "both", "move_type": "sweep", "start_occupancy": "top", "start_position": "back-control", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From a seated rear mount, control the opponent's sleeve as they turn in and come back up on top.\n2. Convert into a side scissor position as they square up.\n3. Get a good grip, shift hips out to the side, and scoop inside the training partner's leg.\n4. Use the pendulum action to secure the sweep and points.", "main_ideas": "Control the sleeve as the opponent turns in. Convert to side scissor and scoop the leg.", "source_time_ranges": []}, {"id": "1dd867eeab5a", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E06 - Scissor and Pendulum Sweeps.mp4", "chapter_title": "The Versatility of The Arm Trap Part 3", "chapter_start": 3963.0, "named_move": "Half guard knee shield arm trap to pendulum sweep", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "half-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From half guard, place a knee shield in front of the training partner as they pass.\n2. Trap an arm as they pass through, grabbing hold of them.\n3. Hit a simple elbow escape to reach the side scissor position with the trap down.\n4. Use the pendulum sweep to come up on top and score.", "main_ideas": "Trap an arm through the knee shield. Elbow escape into side scissor, then pendulum sweep.", "source_time_ranges": []}, {"id": "c5f3d15e3218", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "The Clamp/Hand On Floor - Transition From Closed Guard to The Clamp", "chapter_start": 0, "named_move": "Clamp guard from closed guard", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "clamp*", "technique_steps": "1. From closed guard with opponent's hands on your chest, pull in with your legs.\n2. Bring one hand down to the mat between opponent's arms, separating his hands.\n3. Figure-four grip under the wrist if he has grips, then bring the hand to the mat.\n4. Go around the head inside the bicep and shift hips out to the side.\n5. Pinch one knee in front of the shoulder and one behind the other shoulder to reach clamp position.", "main_ideas": "Pull in with your legs to get hands to the mat. Get between his hands. Pinch with knees to control his head and distance.", "source_time_ranges": []}, {"id": "2adad1cc5bb0", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Trap Triangle from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "", "end_position": "triangle", "technique_steps": "1. From closed guard, pull opponent forward and get his hands down to the mat.\n2. Shoot hips out to the side and lock the clamp.\n3. Place top leg over opponent's shoulder as a hook and use that foot to extract bottom leg.\n4. Lock up the trap triangle with feet locked.\n5. Finish the triangle.", "main_ideas": "Get hands to the mat, then clamp.\nHook the top foot over the shoulder to extract the bottom leg.\nGrab all four knuckles if the opponent grabs your knee.", "source_time_ranges": []}, {"id": "e6f005147fe9", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Figure of Four Triangle from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "clamp*", "end_occupancy": "", "end_position": "triangle", "technique_steps": "1. From the clamp with hands on the mat, hook inside the clavicles.\n2. Bring legs through and lock feet.\n3. Turn hips out to the side, moving the leg across the back.\n4. Lock the figure of four over the opponent for a strangle.", "main_ideas": "Hook inside the clavicles to bring the legs through.\nTurn the hips out and lock the figure of four.", "source_time_ranges": []}, {"id": "1dc5da5e01c7", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Tegatame from Trap Triangle", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "triangle*", "end_occupancy": "", "end_position": "armbar*", "technique_steps": "1. From the trap triangle, place a hand on the opponent's elbow as he pulls away.\n2. Place foot on opponent's lap muscle.\n3. Arch up to the ceiling for the hand lock.", "main_ideas": "Control the elbow from the trap triangle.\nArch up to finish the hand lock.", "source_time_ranges": []}, {"id": "324628ca7c16", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Juji-gatame from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "clamp*", "end_occupancy": "", "end_position": "armbar", "technique_steps": "1. From the clamp, lock the clavicle and bring legs through.\n2. Cross hands to chest or use a three-quarter variation.\n3. Apply the armbar with hips pressed in.", "main_ideas": "Lock the clavicle and bring legs through.\nFinish the armbar with hips driven in.", "source_time_ranges": []}, {"id": "a00fda21486f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Inverted Juji-gatame from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "clamp*", "end_occupancy": "", "end_position": "armbar", "technique_steps": "1. From the clamp with hands on the mat, hold the opponent's elbow.\n2. Place bottom foot on the mat and invert the knee.\n3. Bring the elbow to the floor close to the lap and drive forward for the armbar.", "main_ideas": "Invert the knee to go upside down.\nKeep the elbow close to the lap for the armbar.", "source_time_ranges": []}, {"id": "2793592461a2", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Kimura from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "clamp*", "end_occupancy": "", "end_position": "kimura", "technique_steps": "1. From the clamp with hands on the mat, control the isolated arm's wrist.\n2. Lock the figure of four.\n3. Bring the opponent's elbow to your armpit and the hand inside your thigh.\n4. Apply breaking pressure.", "main_ideas": "Control the wrist from the isolated arm.\nBring the elbow to the armpit for pressure.", "source_time_ranges": []}, {"id": "5f68e3c2c51c", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Ude-gatame from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "clamp*", "end_occupancy": "", "end_position": "armbar", "technique_steps": "1. From the clamp, put a hand on the opponent's elbow and swim the second arm underneath to take the wrist to your collarbone.\n2. Reinforce the elbow with your own hand.\n3. Place your shin in the far armpit and move hips away while head moves toward him.\n4. Apply breaking pressure to the elbow.", "main_ideas": "Reinforce the grip on the elbow with both hands.\nMove hips away and head toward the opponent to break the arm.", "source_time_ranges": []}, {"id": "5dd549224eab", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Attacking From The Clamp", "chapter_start": 416.0, "named_move": "Omoplata from the Clamp", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "clamp*", "end_occupancy": "", "end_position": "omoplata*", "technique_steps": "1. From the clamp with hands on the mat, pommel the foot through and across in front of the opponent.\n2. Hold the sleeve and stretch the leg to bring the opponent's head down first.\n3. Scoot hips away from the opponent, then bring legs in.\n4. Cover the elbow with the shin and drive across the shoulder line to apply kimura pressure.", "main_ideas": "Bring the opponent's head down before raising your own.\nDrive across the shoulder line, not straight forward.", "source_time_ranges": []}, {"id": "4074d501b476", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Trap Triangle/Inside Wrist - Inside Wrist Grip", "chapter_start": 1813.0, "named_move": "Inside Wrist Grip", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From closed guard, break the opponent's posture forward with a knee pull and control his head with your top arm. 2. Shift your hips out to the side to gain an angle, working from your side rather than flat on your back. 3. Take hold of his wrist with your palm up, bend your hand back to about 90 degrees so your thumb joint is higher than his. 4. Keep the grip with your arm extended so he cannot bring his hand back to your chest. 5. Release the grip once it has done its work and move to the next attack.", "main_ideas": "Bend your hand back so your thumb sits high. Break posture forward and control the head first. Work from your side, not flat on your back.", "source_time_ranges": []}, {"id": "ed7a03d2aaf9", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Trap Triangle/Inside Wrist - Inside Wrist Grip", "chapter_start": 1813.0, "named_move": "Trap Triangle", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From the inside wrist grip, bring your foot inside and over your opponent's bicep. 2. Grab your own shin to lock the feet together around his head and one arm. 3. Release the wrist grip once it is no longer needed. 4. Pinch your knees together and pull as he posture up, using the high lock behind his head for leverage.", "main_ideas": "Lock the feet high behind the head. Pinch knees to pull him down. Release the wrist once it has done its job.", "source_time_ranges": []}, {"id": "4b0d0686eb2f", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Trap Triangle/Inside Wrist - Inside Wrist Grip", "chapter_start": 1813.0, "named_move": "Triangle", "ruleset": "both", "move_type": "submission", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "", "end_position": "triangle", "technique_steps": "1. From the trap triangle, if the opponent stands, turn the body so your knee moves behind his head. 2. Control either the shin or the back of his head. 3. Lock the figure of four and tighten the triangle choke.", "main_ideas": "Turn your knee behind his head. Lock the figure of four. Squeeze for the finish.", "source_time_ranges": []}, {"id": "ed197cdfe097", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Trap Triangle/Inside Wrist - Inside Wrist Grip", "chapter_start": 1813.0, "named_move": "Three-Quarter Guard", "ruleset": "both", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "bottom", "end_position": "closed-guard", "technique_steps": "1. From the trap triangle, pass two legs over the opponent's head and shoulders. 2. Use the position to open up armbar opportunities.", "main_ideas": "Pass both legs over the head and shoulders. Set up armbars from here.", "source_time_ranges": []}, {"id": "0e23e15be83d", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E07 - The Clamp.mp4", "chapter_title": "Overhead Sweep", "chapter_start": 3065.0, "named_move": "Overhead Sweep", "ruleset": "both", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, take double sleeve cuff grips with your hands on top of the opponent's hands, ideally with his hands close to your belt.\n2. As the opponent takes the first step to stand, let him step and wait for the vulnerable second step.\n3. Put weight over his hips by bringing your feet down toward the floor.\n4. On the second step, pinch your knees inside and bring your legs together around his upper body.\n5. Bring his hands over your shoulders, with the hands up at shoulder line, narrow or flared.\n6. Extend your two legs so his weight moves forward and his hands start coming toward the mat.\n7. Bring the hands back and around, push off your lower back, and sweep him over one shoulder.\n8. Backward shoulder roll to finish in mount position.", "main_ideas": "Time the sweep to the opponent's second step. Keep the hands on top and close to the belt. Sweep over one shoulder and finish in mount.", "source_time_ranges": []}, {"id": "ab4fe248f21b", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "Attacking A Standing Opponent - applying The Principle of Opportunity: The Scooping Sweep", "chapter_start": 0, "named_move": "Scooping Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "mount", "technique_steps": "1. From closed guard, with the opponent standing and upright, take a cross cuff grip on the opponent.\n2. Bring your elbow to your belt, keeping the grip tight as the opponent pulls their arm out.\n3. Bring your head toward the opponent's ankle and go elbow-deep around the ankle, staying low at the ankle.\n4. Rise your hips and drive upward first, then turn outward so the opponent's knee turns away and their base fails.\n5. Bring your hips forward with elbow to the mat and finish in mount.", "main_ideas": "Control the cross cuff and get low at the ankle. Rise up, then turn outward. Knock the opponent backward and finish in mount.", "source_time_ranges": []}, {"id": "c7381283367b", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "applying The Principle of Opportunity: The Handstand Sweep", "chapter_start": 760.0, "named_move": "Handstand Sweep", "ruleset": "both*", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "standing*", "technique_steps": "1. From closed guard with the opponent standing and cross cuff grip broken, scoop inside the opponent's ankle with the hand. 2. Post the other hand on the floor in a handstand-like base. 3. Drive the hips upward, then turn the knees outward so the opponent's thigh is loaded and he is knocked down to an elbow. 4. Finish with the opponent taken down and the guard player on top.", "main_ideas": "Scoop the ankle and post the hand. Drive the hips up and out. Knock the standing opponent down.", "source_time_ranges": []}, {"id": "bb0a812128eb", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "applying The Principle of Opportunity: The Handstand Sweep", "chapter_start": 760.0, "named_move": "Triangle from Handstand Sweep Recovery", "ruleset": "both*", "move_type": "submission", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "", "end_position": "triangle", "technique_steps": "1. After the handstand sweep leaves the opponent down on an elbow, raise the hips higher than his. 2. Pass one leg over the opponent's shoulder back into closed guard. 3. Grip your own shin, cross the ankles around the head and arm, and turn the knee in behind the head. 4. Lock the figure of four for the triangle finish.", "main_ideas": "Raise the hips above the opponent. Grip your own shin and turn the knee behind the head. Lock the figure of four.", "source_time_ranges": []}, {"id": "d1bb8177fc0e", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "applying The Principle of Opportunity: The Leg Trap Sweep", "chapter_start": 1107.0, "named_move": "Leg Trap Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard, the opponent stands with knees close enough together to lock.\n2. Secure a cuff grip on each of the opponent's arms, forefinger cuff grip on both sides.\n3. As the opponent goes vertical, release the guard and slide down the legs.\n4. Lock both ankles around the opponent's knees, using leg strength to bring the feet together.\n5. Pull the knees in toward the chest to create kazushi, so the opponent's weight goes onto the toes.\n6. Pull the hands in one direction while pointing the knees in the opposite direction to dump the opponent to the mat.\n7. Keep the sleeve grips, head forward and up on an elbow, and use head position to control the opponent as both get up for the score.", "main_ideas": "Lock the ankles around the knees before the opponent settles. Break balance by pulling the knees in. Dump with opposing hand and knee direction, then keep the sleeves and head position.", "source_time_ranges": []}, {"id": "899e7d7f06c9", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "Omoplata Sweeps on a Standing Opponent", "chapter_start": 1343.0, "named_move": "Omoplata Sweep (standing opponent, foot on shoulder)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard with the opponent standing, establish a cross cuff grip (left hand to opponent's left cuff, gripping outside the seam).\n2. Scoop inside the opponent's leg with the free hand or leg.\n3. Place a foot high on the opponent's shoulder (or hip) and turn the body off the shoulder/hip, coming around the corner.\n4. Use the opposite leg as a pendulum to bring the opponent's head down into a forward roll.\n5. Sweep the legs up and over so the opponent rolls onto their back.\n6. Bring the knee down and drive forward so your head is above the opponent's head, sitting high beside them.", "main_ideas": "Control the cuff and turn the corner. Use the pendulum leg to drive the head down. Finish high beside the opponent with your head above theirs.", "source_time_ranges": []}, {"id": "d573a2e3c0e7", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "Omoplata Sweeps on a Standing Opponent", "chapter_start": 1343.0, "named_move": "Omoplata Sweep (standing opponent, pass-off to one-hand control)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard with the opponent standing, establish a cross cuff grip.\n2. Scoop the leg and turn off the hip or shoulder, coming around the corner to lock up.\n3. Pass the grip from left hand to right hand, freeing one hand.\n4. Use the pendulum leg across the body to bring the opponent down into a rotation to the mat.\n5. Roll across the body and recover up.\n6. Pass off a second time to control the opponent's elbow, limiting their ability to turn into you.", "main_ideas": "Pass the grip to free a hand. Rotate the pendulum leg across the body. Control the elbow after the sweep.", "source_time_ranges": []}, {"id": "ee9cfe54a526", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "Omoplata Sweeps on a Standing Opponent", "chapter_start": 1343.0, "named_move": "Omoplata Sweep with Push-Pull (action-reaction)", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. Opponent stands in closed guard; establish cross cuff grip and hook in on the shoulder.\n2. Push backwards with the shin across the opponent's chest, like a scissor sweep, forcing a reaction.\n3. When the opponent pushes back into you, turn and pull through immediately with the omoplata.\n4. Let the opponent's resistance carry them into the forward roll and sweep them to the mat.", "main_ideas": "Push first so the opponent pushes back. Pull through as soon as their resistance appears.", "source_time_ranges": []}, {"id": "da0fbcb80cdd", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "Omoplata Sweeps on a Standing Opponent", "chapter_start": 1343.0, "named_move": "Scoop Sweep to Omoplata Alternation", "ruleset": "gi", "move_type": "transition", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. Opponent stands in closed guard; threaten the scoop sweep by hooking the leg.\n2. When the opponent fights back against the scoop, turn into them and switch to the omoplata in the opposite direction.\n3. If they resist the omoplata, return to the scoop sweep, using their resistance to knock them backwards.\n4. Continue alternating push-pull reactions until the opponent goes to the mat.", "main_ideas": "Threaten one sweep and switch when the opponent resists. Alternate directions to break their balance.", "source_time_ranges": []}, {"id": "fe662215d6ce", "instructor": "John Danaher", "instructional": "Closed Guard - Go Further Faster by John Danaher", "volume": "Closed Guard - Go Further Faster by John Danaher - S01E08 - Standing Opponent.mp4", "chapter_title": "The Double Ankle Sweep", "chapter_start": 2389.0, "named_move": "Double Ankle Sweep", "ruleset": "gi", "move_type": "sweep", "start_occupancy": "bottom", "start_position": "closed-guard", "end_occupancy": "top", "end_position": "side-control", "technique_steps": "1. From closed guard with the opponent standing in combat posture, seize both ankles from the outside with your hands.\n2. Willingly open the closed guard and drop your knees together, pinching them tight so your feet contour to his body.\n3. Drive your pinched knees straight up toward the ceiling to knock him down while keeping hands on the outside of his legs.\n4. Hold a grip on his jacket or over the head, turn your body side on with a base behind you, and get your hips higher than his.\n5. Turn one knee down to the mat and sit over the opposite-side knee, lifting his arm as you drive forward into mount.", "main_ideas": "Keep both hands on the outside of the ankles. Pinch the knees and get high and side on. Finish by sitting over the knee and driving forward.", "source_time_ranges": []}];
